import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
import { Navigate } from 'react-router-dom';
const notification = apiContainer.notification
//GET--->
export async function getNotification(request) {
  try {
    const response = await apiReturnCallBack("GET", notification, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}