//Get Reducer Call--->
export const getThroughRequest = (params?: any) => ({
  type: 'GET_THROUGH_REQUEST',
  payload: params,
});

export const getThroughSuccess = (data: any) => ({
  type: 'GET_THROUGH_SUCCESS',
  payload: { data },
});

export const getThroughFailure = (errorMessage: string) => ({
  type: 'GET_THROUGH_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetThrough = () => ({
  type: 'RESET_GET_THROUGH',
});

