import { call, put, takeEvery } from 'redux-saga/effects';
import { 
  getStaffFaceTraining as getStaffFaceTrainingApi,
  getStaffFaceTrainingById as getStaffFaceTrainingByIdApi 
} from '../../api/FaceTraining';
import { 
  getStaffFaceTrainingSuccess, 
  getStaffFaceTrainingFailure,
  getStaffFaceTrainingByIdSuccess,
  getStaffFaceTrainingByIdFailure
} from './actions';

function* fetchStaffFaceTrainingSaga(action: any): Generator<any, any, any> {
  try {
    const response = yield call(getStaffFaceTrainingApi, action.payload);
    yield put(getStaffFaceTrainingSuccess(response));
  } catch (error: any) {
    const errorMessage =
      error.response && error.response.data && error.response.data.message
        ? error.response.data.message
        : error.message
        ? error.message
        : 'An unexpected error occurred';
    yield put(getStaffFaceTrainingFailure(errorMessage));
  }
}

function* fetchStaffFaceTrainingByIdSaga(action: any): Generator<any, any, any> {
  try {
    const response = yield call(getStaffFaceTrainingByIdApi, action.payload);
    yield put(getStaffFaceTrainingByIdSuccess(response));
  } catch (error: any) {
    const errorMessage =
      error.response?.data?.message || error.message || 'An unexpected error occurred';
    yield put(getStaffFaceTrainingByIdFailure(errorMessage));
  }
}

export default function* StaffFaceTrainingSaga() {
  yield takeEvery('GET_STAFF_FACE_TRAINING_REQUEST', fetchStaffFaceTrainingSaga);
  yield takeEvery('GET_STAFF_FACE_TRAINING_BY_ID_REQUEST', fetchStaffFaceTrainingByIdSaga);
}