//Get Reducer Call--->
export const getVisitPlacesRequest = (params?: any) => ({
  type: 'GET_VISIT_PLACES_REQUEST',
  payload: params,
});

export const getVisitPlacesSuccess = (data: any) => ({
  type: 'GET_VISIT_PLACES_SUCCESS',
  payload: { data },
});

export const getVisitPlacesFailure = (errorMessage: string) => ({
  type: 'GET_VISIT_PLACES_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetVisitPlaces = () => ({
  type: 'RESET_GET_VISIT_PLACES',
});

