import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
import { Navigate } from 'react-router-dom';
const settingDeduction = apiContainer.settingDeduction
//GET--->
export async function getSettingDeduction(request) {
  try {
    const response = await apiReturnCallBack("GET", settingDeduction, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//CREATE---->
export async function createSettingDeduction(request) {
  try {
    const response = await apiReturnCallBack("POST", settingDeduction, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//UPDATE---->
export async function updateSettingDeduction(request, settingDeductionId) {
  try {
    const response = await apiReturnCallBack("PUT", settingDeduction + `/${settingDeductionId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
