import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
const addLoan = apiContainer.addLoan;
const addPayment = apiContainer.addPayment;
const paymentHistory = apiContainer.paymentHistory;
const loanList = apiContainer.loanList;
const loanListDetails = apiContainer.loanListDetails;

//GET--->
export async function getAddLoan(request) {
    try {
        const response = await apiReturnCallBack('GET', addLoan, request);
        const data = await response.json();
        if (!response.ok) {
            throw new Error(data.message || JSON.stringify(data));
        }
        return data;
    } catch (error) {
        console.error(error);
        throw error;
    }
}
