import { Navigate } from 'react-router-dom';
import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
const through = apiContainer.through
//GET--->
export async function getThrough(request) {
  try {
    const response = await apiReturnCallBack("GET", through, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//CREATE---->
export async function createThrough(request) {
  try {
    const response = await apiReturnCallBack("POST", through, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//UPDATE---->
export async function updateThrough(request, throughId) {
  try {
    const response = await apiReturnCallBack("PUT", through + `/${throughId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
