import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
import { Navigate } from 'react-router-dom';
const StaffGeoLocations = apiContainer.staffGeoLocations
const AllStaffGeoLocations = apiContainer.allstaffGeoLocations
const AllStaffProductivity = apiContainer.allStaffProductivity
const StaffProductivity = apiContainer.staffProductivity
const AllStaffAttendance = apiContainer.allStaffAttendance
const StaffClientVisit = apiContainer.staffClientVisit
const BranchLocationEntryLog = apiContainer.branchLocationEntryLog
//GET--->
export async function getStaffGeolocations(request) {
  try {
    const response = await apiReturnCallBack("GET",StaffGeoLocations, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

