// GET staff geolocations with query parameters
export async function getStaffIdGeolocations(request) {
  try {
    // Build query string from request object
    const queryParams = new URLSearchParams(request).toString();
    const url = queryParams ? `${StaffGeoLocations}?${queryParams}` : StaffGeoLocations;
    
    const response = await apiReturnCallBack("GET", url, null);
    const data = await response.json();
    
    if (!response.ok) {
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />;
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

