interface StaffFaceTrainingState {
  getStaffFaceTrainingList: any[];
  getStaffFaceTrainingByIdData: any | null;
  isLoading: boolean;
  errorMessage: string | null;
  getStaffFaceTrainingSuccess: boolean;
  getStaffFaceTrainingFailure: boolean;
  getStaffFaceTrainingByIdSuccess: boolean;
  getStaffFaceTrainingByIdFailure: boolean;
}

const initialState: StaffFaceTrainingState = {
  getStaffFaceTrainingList: [],
  getStaffFaceTrainingByIdData: null,
  isLoading: false,
  errorMessage: null,
  getStaffFaceTrainingSuccess: false,
  getStaffFaceTrainingFailure: false,
  getStaffFaceTrainingByIdSuccess: false,
  getStaffFaceTrainingByIdFailure: false,
};

export default function StaffFaceTrainingReducer(state = initialState, action: any) {
  switch (action.type) {
    // GET Staff Face Training List Cases
    case 'GET_STAFF_FACE_TRAINING_REQUEST':
      return {
        ...state,
        isLoading: true,
        getStaffFaceTrainingSuccess: false,
        getStaffFaceTrainingFailure: false,
        errorMessage: null,
      };

    case 'GET_STAFF_FACE_TRAINING_SUCCESS':
      return {
        ...state,
        isLoading: false,
        getStaffFaceTrainingSuccess: true,
        getStaffFaceTrainingFailure: false,
        getStaffFaceTrainingList: action.payload.data || [],
        errorMessage: null,
      };

    case 'GET_STAFF_FACE_TRAINING_FAILURE':
      return {
        ...state,
        isLoading: false,
        getStaffFaceTrainingFailure: true,
        getStaffFaceTrainingSuccess: false,
        errorMessage: action.errorMessage.errorMessage,
      };

    case 'RESET_GET_STAFF_FACE_TRAINING':
      return {
        ...state,
        getStaffFaceTrainingList: [],
        getStaffFaceTrainingSuccess: false,
        getStaffFaceTrainingFailure: false,
        errorMessage: null,
      };

    // GET Staff Face Training by ID Cases
    case 'GET_STAFF_FACE_TRAINING_BY_ID_REQUEST':
      return {
        ...state,
        isLoading: true,
        getStaffFaceTrainingByIdSuccess: false,
        getStaffFaceTrainingByIdFailure: false,
        errorMessage: null,
      };

    case 'GET_STAFF_FACE_TRAINING_BY_ID_SUCCESS':
      return {
        ...state,
        isLoading: false,
        getStaffFaceTrainingByIdSuccess: true,
        getStaffFaceTrainingByIdFailure: false,
        getStaffFaceTrainingByIdData: action.payload.data || null,
        errorMessage: null,
      };

    case 'GET_STAFF_FACE_TRAINING_BY_ID_FAILURE':
      return {
        ...state,
        isLoading: false,
        getStaffFaceTrainingByIdFailure: true,
        getStaffFaceTrainingByIdSuccess: false,
        errorMessage: action.errorMessage.errorMessage,
      };

    case 'RESET_GET_STAFF_FACE_TRAINING_BY_ID':
      return {
        ...state,
        getStaffFaceTrainingByIdData: null,
        getStaffFaceTrainingByIdSuccess: false,
        getStaffFaceTrainingByIdFailure: false,
        errorMessage: null,
      };

    default:
      return state;
  }
}