// employee/reducers.ts
const initialState = {
  getPetrolAllowanceList: [],
  getPetrolAllowanceReportData: [],
  createPetrolAllowanceData: null,
  updatePetrolAllowanceData: null,
  isLoading: false,
  errorMessage: null,
  getPetrolAllowanceSuccess: false,
  getPetrolAllowanceFailure: false,
  getPetrolAllowanceReportSuccess: false,
  getPetrolAllowanceReportFailure: false,
  createPetrolAllowanceSuccess: false,
  createPetrolAllowanceFailure: false,
  updatePetrolAllowanceSuccess: false,
  updatePetrolAllowanceFailure: false,
  deletePetrolAllowanceSuccess: false,
  deletePetrolAllowanceFailure: false,
  approvePetrolAllowanceImageSuccess: false,
  approvePetrolAllowanceImageFailure: false,
  approvePetrolAllowanceImageData: null,
  disapprovePetrolAllowanceImageSuccess: false,
  disapprovePetrolAllowanceImageFailure: false,
  disapprovePetrolAllowanceImageData: null,
};

export default function petrolAllowanceReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_PETROL_ALLOWANCE_SUCCESS": {
      return {
        ...state,
        getPetrolAllowanceSuccess: true,
        getPetrolAllowanceList: action.payload.data || [],
        getPetrolAllowanceFailure: false,
      };
    }
    case "GET_PETROL_ALLOWANCE_FAILURE": {
      return {
        ...state,
        getPetrolAllowanceFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getPetrolAllowanceSuccess: false,
      };
    }
    case "RESET_GET_PETROL_ALLOWANCE": {
      return {
        ...state,
        getPetrolAllowanceSuccess: false,
        getPetrolAllowanceFailure: false,
        getPetrolAllowanceList: [],
        errorMessage: null,
      };
    }

    case "GET_PETROL_ALLOWANCE_REPORT_SUCCESS": {
      return {
        ...state,
        getPetrolAllowanceReportSuccess: true,
        getPetrolAllowanceReportData: action.payload.data || [],
        getPetrolAllowanceReportFailure: false,
      };
    }
    case "GET_PETROL_ALLOWANCE_REPORT_FAILURE": {
      return {
        ...state,
        getPetrolAllowanceReportFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getPetrolAllowanceReportSuccess: false,
      };
    }
    case "RESET_GET_PETROL_REPORT_ALLOWANCE": {
      return {
        ...state,
        getPetrolAllowanceReportSuccess: false,
        getPetrolAllowanceReportFailure: false,
        getPetrolAllowanceReportData: [],
        errorMessage: null,
      };
    }

    case "CREATE_PETROL_ALLOWANCE_SUCCESS": {
      return {
        ...state,
        createPetrolAllowanceSuccess: true,
        createPetrolAllowanceData: action.payload.data || null,
        createPetrolAllowanceFailure: false,
      };
    }
    case "CREATE_PETROL_ALLOWANCE_FAILURE": {
      return {
        ...state,
        createPetrolAllowanceFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        createPetrolAllowanceSuccess: false,
      };
    }
    case "RESET_CREATE_PETROL_ALLOWANCE": {
      return {
        ...state,
        createPetrolAllowanceSuccess: false,
        createPetrolAllowanceFailure: false,
        createPetrolAllowanceData: null,
        errorMessage: null,
      };
    }

    case "UPDATE_PETROL_ALLOWANCE_SUCCESS": {
      return {
        ...state,
        updatePetrolAllowanceSuccess: true,
        updatePetrolAllowanceData: action.payload.data || null,
        updatePetrolAllowanceFailure: false,
      };
    }
    case "UPDATE_PETROL_ALLOWANCE_FAILURE": {
      return {
        ...state,
        updatePetrolAllowanceFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updatePetrolAllowanceSuccess: false,
      };
    }
    case "RESET_UPDATE_PETROL_ALLOWANCE": {
      return {
        ...state,
        updatePetrolAllowanceSuccess: false,
        updatePetrolAllowanceFailure: false,
        updatePetrolAllowanceData: null,
        errorMessage: null,
      };
    }

    case "APPROVE_PETROL_ALLOWANCE_IMAGE_SUCCESS": {
      return {
        ...state,
        approvePetrolAllowanceImageSuccess: true,
        approvePetrolAllowanceImageData: action.payload.data || null,
        approvePetrolAllowanceImageFailure: false,
      };
    }
    case "APPROVE_PETROL_ALLOWANCE_IMAGE_FAILURE": {
      return {
        ...state,
        approvePetrolAllowanceImageFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        approvePetrolAllowanceImageSuccess: false,
      };
    }
    case "RESET_APPROVE_PETROL_ALLOWANCE_IMAGE": {
      return {
        ...state,
        approvePetrolAllowanceImageSuccess: false,
        approvePetrolAllowanceImageFailure: false,
        approvePetrolAllowanceImageData: null,
        errorMessage: null,
      };
    }


    case "DISAPPROVE_PETROL_ALLOWANCE_IMAGE_SUCCESS": {
      return {
        ...state,
        disapprovePetrolAllowanceImageSuccess: true,
        disapprovePetrolAllowanceImageData: action.payload.data || null,
        disapprovePetrolAllowanceImageFailure: false,
      };
    }
    case "DISAPPROVE_PETROL_ALLOWANCE_IMAGE_FAILURE": {
      return {
        ...state,
        disapprovePetrolAllowanceImageFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        disapprovePetrolAllowanceImageSuccess: false,
      };
    }
    case "RESET_DISAPPROVE_PETROL_ALLOWANCE_IMAGE": {
      return {
        ...state,
        disapprovePetrolAllowanceImageSuccess: false,
        disapprovePetrolAllowanceImageFailure: false,
        disapprovePetrolAllowanceImageData: null,
        errorMessage: null,
      };
    }

    // case "DELETE_PETROL_ALLOWANCE_SUCCESS": {
    //   return {
    //     ...state,
    //     deletePetrolAllowanceSuccess: true,
    //     deletePetrolAllowanceFailure: false,
    //   };
    // }
    // case "DELETE_PETROL_ALLOWANCE_FAILURE": {
    //   return {
    //     ...state,
    //     deletePetrolAllowanceFailure: true,
    //     errorMessage: action.errorMessage.errorMessage,
    //     deletePetrolAllowanceSuccess: false,
    //   };
    // }
    // case "RESET_DELETE_PETROL_ALLOWANCE": {
    //   return {
    //     ...state,
    //     deletePetrolAllowanceSuccess: false,
    //     deletePetrolAllowanceFailure: false,
    //     errorMessage: null,
    //   };
    // }

    default: {
      return state;
    }
  }
}
