import { Navigate } from 'react-router-dom';
import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
const settingsCompanyInfo = apiContainer.settingsCompanyInfo
//GET--->
export async function getSettingsCompanyInfo(request) {
  try {
    const response = await apiReturnCallBack("GET", settingsCompanyInfo, request);
    const data = await response.json();
    if (!response.ok) {
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

//UPDATE---->
export async function updateSettingsCompanyInfo(request, settingsCompanyInfoId) {
  try {
    const response = await apiReturnCallBack("PUT", settingsCompanyInfo+`/${settingsCompanyInfoId}`, request);
    const data = await response.json();
    if (!response.ok) {
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
