// saga.ts (updated to match your API response structure)
import { call, put, takeEvery } from 'redux-saga/effects';
import {
 getStaffGeolocations,
 getAllStaffGeolocations,
 getStaffIdGeolocations,
 getAllStaffAttendance,
 getAllStaffProductivity,
 getStaffIdProductivity,
 getStaffIdClientVisit,
 getBranchLocationEntryLogs,
} from '../../api/StaffGeoLocationsApi';
import {
 getStaffGeolocationsSuccess,
 getStaffGeolocationsFailure,
 getAllStaffGeolocationsSuccess,
 getAllStaffGeolocationsFailure,
 getStaffIdGeolocationsSuccess,
 getStaffIdGeolocationsFailure,
 getAllStaffAttendanceSuccess,
 getAllStaffAttendanceFailure,
 getAllStaffProductivitySuccess,
 getAllStaffProductivityFailure,
 getStaffIdProductivitySuccess,
 getStaffIdProductivityFailure,
 getStaffIdClientVisitSuccess,
 getStaffIdClientVisitFailure,
 getBranchLocationEntryLogsSuccess,
 getBranchLocationEntryLogsFailure,
} from './actions';

function* fetchStaffGeolocationsSaga(action: any): Generator<any, any, any> {
 try {
  const response = yield call(getStaffGeolocations, action.payload);
  yield put(getStaffGeolocationsSuccess(response.data));
 } catch (error: any) {
  const errorMessage =
   error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
    ? error.message
    : 'An unexpected error occurred';
  yield put(getStaffGeolocationsFailure(errorMessage));
 }
}

