function* fetchStaffIdProductivitySaga(action: any): Generator<any, any, any> {
 try {
  const response = yield call(getStaffIdProductivity, action.payload);
  // FIX Bug 3: API functions return the full parsed JSON; pass .data so the
  // reducer receives the actual payload, not the { data, error, message } wrapper.
  yield put(getStaffIdProductivitySuccess(response.data));
 } catch (error: any) {
  const errorMessage = error.message || 'An unexpected error occurred';
  yield put(getStaffIdProductivityFailure(errorMessage));
 }
}

function* fetchStaffIdClientVisitSaga(action: any): Generator<any, any, any> {
 try {
  const response = yield call(getStaffIdClientVisit, action.payload);
  // FIX Bug 3: same as above — pass .data so the list is the real array
  yield put(getStaffIdClientVisitSuccess(response.data));
 } catch (error: any) {
  const errorMessage = error.message || 'An unexpected error occurred';
  yield put(getStaffIdClientVisitFailure(errorMessage));
 }
}

function* fetchBranchLocationEntryLogsSaga(action: any): Generator<any, any, any> {
 try {
  const response = yield call(getBranchLocationEntryLogs, action.payload);
  // Backend returns { data: [...], error: false, ... }
  // Response.data is the array, so we wrap it correctly for the reducer
  yield put(getBranchLocationEntryLogsSuccess({ data: response.data }));
 } catch (error: any) {
  const errorMessage = error.message || 'An unexpected error occurred';
  yield put(getBranchLocationEntryLogsFailure(errorMessage));
 }
}

export default function* StaffSaga() {
 yield takeEvery('GET_STAFF_GEOLOCATIONS_REQUEST', fetchStaffGeolocationsSaga);
 yield takeEvery('GET_ALL_STAFF_GEOLOCATIONS_REQUEST', fetchAllStaffGeolocationsSaga);
 yield takeEvery('GET_STAFF_ID_GEOLOCATIONS_REQUEST', fetchStaffIdGeolocationsSaga);
 yield takeEvery('GET_ALL_STAFF_ATTENDANCE_REQUEST', fetchAllStaffAttendanceSaga);
 yield takeEvery('GET_ALL_STAFF_PRODUCTIVITY_REQUEST', fetchAllStaffProductivitySaga);
 yield takeEvery('GET_STAFF_ID_PRODUCTIVITY_REQUEST', fetchStaffIdProductivitySaga);
 yield takeEvery('GET_STAFF_ID_CLIENT_VISIT_REQUEST', fetchStaffIdClientVisitSaga);
 yield takeEvery('GET_BRANCH_LOCATION_ENTRY_LOGS_REQUEST', fetchBranchLocationEntryLogsSaga);
}
