// employee/reducers.ts
const initialState = {
  getSettingDeductionList: [],
  createSettingDeductionData: null,
  updateSettingDeductionData: null,
  isLoading: false,
  errorMessage: null,
  getSettingDeductionSuccess: false,
  getSettingDeductionFailure: false,
  createSettingDeductionSuccess: false,
  createSettingDeductionFailure: false,
  updateSettingDeductionSuccess: false,
  updateSettingDeductionFailure: false,
  deleteSettingDeductionSuccess: false,
  deleteSettingDeductionFailure: false,
};

export default function settingDeductionReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_SETTING_DEDUCTION_SUCCESS": {
      return {
        ...state,
        getSettingDeductionSuccess: true,
        getSettingDeductionList: action.payload.data.data,
        getSettingDeductionFailure: false,
      };
    }
    case "GET_SETTING_DEDUCTION_FAILURE": {
      return {
        ...state,
        getSettingDeductionFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getSettingDeductionSuccess: false,
      };
    }
    case "RESET_GET_SETTING_DEDUCTION": {
      return {
        ...state,
        getSettingDeductionSuccess: false,
        getSettingDeductionFailure: false,
        getSettingDeductionList: [],
        errorMessage: null,
      };
    }

    case "CREATE_SETTING_DEDUCTION_SUCCESS": {
      return {
        ...state,
        createSettingDeductionSuccess: true,
        createSettingDeductionData: action.payload.data.data,
        createSettingDeductionFailure: false,
      };
    }
    case "CREATE_SETTING_DEDUCTION_FAILURE": {
      return {
        ...state,
        createSettingDeductionFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        createSettingDeductionSuccess: false,
      };
    }
    case "RESET_CREATE_SETTING_DEDUCTION": {
      return {
        ...state,
        createSettingDeductionSuccess: false,
        createSettingDeductionFailure: false,
        createSettingDeductionData: null,
        errorMessage: null,
      };
    }

    case "UPDATE_SETTING_DEDUCTION_SUCCESS": {
      return {
        ...state,
        updateSettingDeductionSuccess: true,
        updateSettingDeductionData: action.payload.data.data,
        updateSettingDeductionFailure: false,
      };
    }
    case "UPDATE_SETTING_DEDUCTION_FAILURE": {
      return {
        ...state,
        updateSettingDeductionFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updateSettingDeductionSuccess: false,
      };
    }
    case "RESET_UPDATE_SETTING_DEDUCTION": {
      return {
        ...state,
        updateSettingDeductionSuccess: false,
        updateSettingDeductionFailure: false,
        updateSettingDeductionData: null,
        errorMessage: null,
      };
    }

    // case "DELETE_SETTING_DEDUCTION_SUCCESS": {
    //   return {
    //     ...state,
    //     deleteSettingDeductionSuccess: true,
    //     deleteSettingDeductionFailure: false,
    //   };
    // }
    // case "DELETE_SETTING_DEDUCTION_FAILURE": {
    //   return {
    //     ...state,
    //     deleteSettingDeductionFailure: true,
    //     errorMessage: action.errorMessage.errorMessage,
    //     deleteSettingDeductionSuccess: false,
    //   };
    // }
    // case "RESET_DELETE_SETTING_DEDUCTION": {
    //   return {
    //     ...state,
    //     deleteSettingDeductionSuccess: false,
    //     deleteSettingDeductionFailure: false,
    //     errorMessage: null,
    //   };
    // }

    default: {
      return state;
    }
  }
}
