// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import { createVisitPlaces, getVisitPlaces, updateVisitPlaces } from '../../api/VisitPlacesApi'; // Adjust the path as needed
import { 
  getVisitPlacesSuccess, getVisitPlacesFailure,
  createVisitPlacesSuccess,
  createVisitPlacesFailure,
  updateVisitPlacesSuccess,
  updateVisitPlacesFailure,
} from './actions';

// Saga to handle fetching visitPlacess
function* fetchVisitPlacesSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getVisitPlaces, action.payload);
    yield put(getVisitPlacesSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(getVisitPlacesFailure(errorMessage));
  }
}

// // Saga to handle creating a visitPlaces
function* createVisitPlacesSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(createVisitPlaces, action.payload);
    yield put(createVisitPlacesSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(createVisitPlacesFailure(errorMessage));
  }
}

// // Saga to handle updating a visitPlaces
function* updateVisitPlacesSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(updateVisitPlaces, action.payload.data, action.payload.id);
    yield put(updateVisitPlacesSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(updateVisitPlacesFailure(errorMessage));
  }
}

