export default function* visitPlacesSaga() {
  yield takeEvery('GET_VISIT_PLACES_REQUEST', fetchVisitPlacesSaga);
  yield takeEvery('CREATE_VISIT_PLACES_REQUEST', createVisitPlacesSaga);
  yield takeEvery('UPDATE_VISIT_PLACES_REQUEST', updateVisitPlacesSaga);
  // yield takeEvery('DELETE_VISIT_PLACES_REQUEST', deleteVisitPlacesSaga);
}
