const initialState = {
    getNotificationList: [],
    isLoading: false,
    errorMessage: null,
    getNotificationSuccess: false,
    getNotificationFailure: false,
  };
  
  export default function notificationReducer(state = initialState, action: any) {
    switch (action.type) {
      case "GET_NOTIFICATION_REQUEST":
        return {
          ...state,
          isLoading: true,
          errorMessage: null,
        };
        
      case "GET_NOTIFICATION_SUCCESS":
        return {
          ...state,
          isLoading: false,
          getNotificationSuccess: true,
          getNotificationFailure: false,
          getNotificationList: action.payload.data.data,
        };
        
      case "GET_NOTIFICATION_FAILURE":
        return {
          ...state,
          isLoading: false,
          getNotificationFailure: true,
          errorMessage: action.errorMessage.errorMessage,
          getNotificationSuccess: false,
        };
        
      case "RESET_GET_NOTIFICATION":
        return {
          ...state,
          getNotificationSuccess: false,
          getNotificationFailure: false,
          getNotificationList: [],
          errorMessage: null,
        };
        
      default:
        return state;
    }
  }