// employee/reducers.ts
const initialState = {
  getThroughList: [],
  createThroughData: null,
  updateThroughData: null,
  isLoading: false,
  errorMessage: null,
  getThroughSuccess: false,
  getThroughFailure: false,
  createThroughSuccess: false,
  createThroughFailure: false,
  updateThroughSuccess: false,
  updateThroughFailure: false,
  deleteThroughSuccess: false,
  deleteThroughFailure: false,
};

export default function throughReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_THROUGH_SUCCESS": {
      return {
        ...state,
        getThroughSuccess: true,
        getThroughList: action.payload.data.data,
        getThroughFailure: false,
      };
    }
    case "GET_THROUGH_FAILURE": {
      return {
        ...state,
        getThroughFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getThroughSuccess: false,
      };
    }
    case "RESET_GET_THROUGH": {
      return {
        ...state,
        getThroughSuccess: false,
        getThroughFailure: false,
        getThroughList: [],
        errorMessage: null,
      };
    }

    case "CREATE_THROUGH_SUCCESS": {
      return {
        ...state,
        createThroughSuccess: true,
        createThroughData: action.payload.data.data,
        createThroughFailure: false,
      };
    }
    case "CREATE_THROUGH_FAILURE": {
      return {
        ...state,
        createThroughFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        createThroughSuccess: false,
      };
    }
    case "RESET_CREATE_THROUGH": {
      return {
        ...state,
        createThroughSuccess: false,
        createThroughFailure: false,
        createThroughData: null,
        errorMessage: null,
      };
    }

    case "UPDATE_THROUGH_SUCCESS": {
      return {
        ...state,
        updateThroughSuccess: true,
        updateThroughData: action.payload.data.data,
        updateThroughFailure: false,
      };
    }
    case "UPDATE_THROUGH_FAILURE": {
      return {
        ...state,
        updateThroughFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updateThroughSuccess: false,
      };
    }
    case "RESET_UPDATE_THROUGH": {
      return {
        ...state,
        updateThroughSuccess: false,
        updateThroughFailure: false,
        updateThroughData: null,
        errorMessage: null,
      };
    }

    case "DELETE_THROUGH_SUCCESS": {
      return {
        ...state,
        deleteThroughSuccess: true,
        deleteThroughFailure: false,
      };
    }
    case "DELETE_THROUGH_FAILURE": {
      return {
        ...state,
        deleteThroughFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        deleteThroughSuccess: false,
      };
    }
    case "RESET_DELETE_THROUGH": {
      return {
        ...state,
        deleteThroughSuccess: false,
        deleteThroughFailure: false,
        errorMessage: null,
      };
    }

    default: {
      return state;
    }
  }
}
