// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import { createThrough, getThrough, updateThrough } from '../../api/ThroughApi'; // Adjust the path as needed
import { 
  getThroughSuccess, getThroughFailure,
  createThroughSuccess,
  createThroughFailure,
  updateThroughSuccess,
  updateThroughFailure,
} from './actions';

// Saga to handle fetching throughs
function* fetchThroughSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getThrough, action.payload);
    yield put(getThroughSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(getThroughFailure(errorMessage));
  }
}

// // Saga to handle creating a through
function* createThroughSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(createThrough, action.payload);
    yield put(createThroughSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(createThroughFailure(errorMessage));
  }
}

// // Saga to handle updating a through
function* updateThroughSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(updateThrough, action.payload.data, action.payload.id);
    yield put(updateThroughSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(updateThroughFailure(errorMessage));
  }
}

