export default function* throughSaga() {
  yield takeEvery('GET_THROUGH_REQUEST', fetchThroughSaga);
  yield takeEvery('CREATE_THROUGH_REQUEST', createThroughSaga);
  yield takeEvery('UPDATE_THROUGH_REQUEST', updateThroughSaga);
  // yield takeEvery('DELETE_THROUGH_REQUEST', deleteThroughSaga);
}
