// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import { createSettingDeduction, getSettingDeduction, updateSettingDeduction } from '../../api/SettingDeductionApi'; // Adjust the path as needed
import {
  getSettingDeductionSuccess,
  getSettingDeductionFailure,
  createSettingDeductionSuccess,
  createSettingDeductionFailure,
  updateSettingDeductionSuccess,
  updateSettingDeductionFailure,
} from './actions';

// Saga to handle fetching settingDeductions
function* fetchSettingDeductionSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getSettingDeduction, action.payload);
    yield put(getSettingDeductionSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
      ? error.response.data.message
      : error.message
        ? error.message
        : 'An unexpected error occurred';
    yield put(getSettingDeductionFailure(errorMessage));
  }
}

// // Saga to handle creating a settingDeduction
function* createSettingDeductionSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(createSettingDeduction, action.payload);
    yield put(createSettingDeductionSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
      ? error.response.data.message
      : error.message
        ? error.message
        : 'An unexpected error occurred';

    yield put(createSettingDeductionFailure(errorMessage));
  }
}

// // Saga to handle updating a settingDeduction
function* updateSettingDeductionSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(updateSettingDeduction, action.payload.data, action.payload.id);
    yield put(updateSettingDeductionSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
      ? error.response.data.message
      : error.message
        ? error.message
        : 'An unexpected error occurred';
    yield put(updateSettingDeductionFailure(errorMessage));
  }
}

