export default function* settingDeductionSaga() {
  yield takeEvery('GET_SETTING_DEDUCTION_REQUEST', fetchSettingDeductionSaga);
  yield takeEvery('CREATE_SETTING_DEDUCTION_REQUEST', createSettingDeductionSaga);
  yield takeEvery('UPDATE_SETTING_DEDUCTION_REQUEST', updateSettingDeductionSaga);
  // yield takeEvery('DELETE_SETTING_DEDUCTION_REQUEST', deleteSettingDeductionSaga);
}
