// employee/reducers.ts
const initialState = {
  getVisitPlacesList: [],
  createVisitPlacesData: null,
  updateVisitPlacesData: null,
  isLoading: false,
  errorMessage: null,
  getVisitPlacesSuccess: false,
  getVisitPlacesFailure: false,
  createVisitPlacesSuccess: false,
  createVisitPlacesFailure: false,
  updateVisitPlacesSuccess: false,
  updateVisitPlacesFailure: false,
  deleteVisitPlacesSuccess: false,
  deleteVisitPlacesFailure: false,
};

export default function visitPlacesReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_VISIT_PLACES_SUCCESS": {
      return {
        ...state,
        getVisitPlacesSuccess: true,
        getVisitPlacesList: action.payload.data.data,
        getVisitPlacesFailure: false,
      };
    }
    case "GET_VISIT_PLACES_FAILURE": {
      return {
        ...state,
        getVisitPlacesFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getVisitPlacesSuccess: false,
      };
    }
    case "RESET_GET_VISIT_PLACES": {
      return {
        ...state,
        getVisitPlacesSuccess: false,
        getVisitPlacesFailure: false,
        getVisitPlacesList: [],
        errorMessage: null,
      };
    }

    case "CREATE_VISIT_PLACES_SUCCESS": {
      return {
        ...state,
        createVisitPlacesSuccess: true,
        createVisitPlacesData: action.payload.data.data,
        createVisitPlacesFailure: false,
      };
    }
    case "CREATE_VISIT_PLACES_FAILURE": {
      return {
        ...state,
        createVisitPlacesFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        createVisitPlacesSuccess: false,
      };
    }
    case "RESET_CREATE_VISIT_PLACES": {
      return {
        ...state,
        createVisitPlacesSuccess: false,
        createVisitPlacesFailure: false,
        createVisitPlacesData: null,
        errorMessage: null,
      };
    }

    case "UPDATE_VISIT_PLACES_SUCCESS": {
      return {
        ...state,
        updateVisitPlacesSuccess: true,
        updateVisitPlacesData: action.payload.data.data,
        updateVisitPlacesFailure: false,
      };
    }
    case "UPDATE_VISIT_PLACES_FAILURE": {
      return {
        ...state,
        updateVisitPlacesFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updateVisitPlacesSuccess: false,
      };
    }
    case "RESET_UPDATE_VISIT_PLACES": {
      return {
        ...state,
        updateVisitPlacesSuccess: false,
        updateVisitPlacesFailure: false,
        updateVisitPlacesData: null,
        errorMessage: null,
      };
    }

    case "DELETE_VISIT_PLACES_SUCCESS": {
      return {
        ...state,
        deleteVisitPlacesSuccess: true,
        deleteVisitPlacesFailure: false,
      };
    }
    case "DELETE_VISIT_PLACES_FAILURE": {
      return {
        ...state,
        deleteVisitPlacesFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        deleteVisitPlacesSuccess: false,
      };
    }
    case "RESET_DELETE_VISIT_PLACES": {
      return {
        ...state,
        deleteVisitPlacesSuccess: false,
        deleteVisitPlacesFailure: false,
        errorMessage: null,
      };
    }

    default: {
      return state;
    }
  }
}
