//Get Reducer Call--->
export const getAccountRequest = (params?: any) => ({
  type: 'GET_ACCOUNT_REQUEST',
  payload: params,
});

export const getAccountSuccess = (data: any) => ({
  type: 'GET_ACCOUNT_SUCCESS',
  payload: { data },
});

export const getAccountFailure = (errorMessage: string) => ({
  type: 'GET_ACCOUNT_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetAccount = () => ({
  type: 'RESET_GET_ACCOUNT',
});

//Create Reducer Call--->
export const createAccountRequest = (data: any) => ({
  type: 'CREATE_ACCOUNT_REQUEST',
  payload: data,
});

export const createAccountSuccess = (data: any) => ({
  type: 'CREATE_ACCOUNT_SUCCESS',
  payload: { data },
});

export const createAccountFailure = (errorMessage: string) => ({
  type: 'CREATE_ACCOUNT_FAILURE',
  errorMessage: { errorMessage },
});

export const resetCreateAccount = () => ({
  type: 'RESET_CREATE_ACCOUNT',
});

//Update Reducer Call--->
export const updateAccountRequest = ( data: any, id: string) => ({
  type: 'UPDATE_ACCOUNT_REQUEST',
  payload: { data, id },
});

export const updateAccountSuccess = (data: any) => ({
  type: 'UPDATE_ACCOUNT_SUCCESS',
  payload: { data },
});

export const updateAccountFailure = (errorMessage: string) => ({
  type: 'UPDATE_ACCOUNT_FAILURE',
  errorMessage: { errorMessage },
});

export const resetUpdateAccount = () => ({
  type: 'RESET_UPDATE_ACCOUNT',
});
//Delete Reducer Call--->
export const deleteAccountRequest = ( id: string) => ({
  type: 'DELETE_ACCOUNT_REQUEST',
  payload: { id },
});

export const deleteAccountSuccess = (data: any) => ({
  type: 'DELETE_ACCOUNT_SUCCESS',
  payload: { data },
});

export const deleteAccountFailure = (errorMessage: string) => ({
  type: 'DELETE_ACCOUNT_FAILURE',
  errorMessage: { errorMessage },
});

export const deleteUpdateAccount = () => ({
  type: 'RESET_DELETE_ACCOUNT',
});
