// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import { createAccount, getAccount, updateAccount } from '../../api/AccountApi'; // Adjust the path as needed
import { 
  getAccountSuccess, getAccountFailure,
  createAccountSuccess,
  createAccountFailure,
  updateAccountSuccess,
  updateAccountFailure,
} from './actions';

// Saga to handle fetching accounts
function* fetchAccountSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getAccount, action.payload);
    yield put(getAccountSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(getAccountFailure(errorMessage));
  }
}

// // Saga to handle creating a account
function* createAccountSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(createAccount, action.payload);
    yield put(createAccountSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(createAccountFailure(errorMessage));
  }
}

// // Saga to handle updating a account
function* updateAccountSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(updateAccount, action.payload.data, action.payload.id);
    yield put(updateAccountSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
    ? error.response.data.message
    : error.message
      ? error.message
      : 'An unexpected error occurred';

    yield put(updateAccountFailure(errorMessage));
  }
}

