export default function* accountSaga() {
  yield takeEvery('GET_ACCOUNT_REQUEST', fetchAccountSaga);
  yield takeEvery('CREATE_ACCOUNT_REQUEST', createAccountSaga);
  yield takeEvery('UPDATE_ACCOUNT_REQUEST', updateAccountSaga);
  // yield takeEvery('DELETE_ACCOUNT_REQUEST', deleteAccountSaga);
}
