// Get Notification Reducer Call
export const getNotificationRequest = (params?: any) => ({
    type: 'GET_NOTIFICATION_REQUEST',
    payload: params,
  });
  
  export const getNotificationSuccess = (data: any) => ({
    type: 'GET_NOTIFICATION_SUCCESS',
    payload: { data },
  });
  
  export const getNotificationFailure = (errorMessage: string) => ({
    type: 'GET_NOTIFICATION_FAILURE',
    errorMessage: { errorMessage },
  });
  
  export const resetGetNotification = () => ({
    type: 'RESET_GET_NOTIFICATION',
  });