import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
import { Navigate } from 'react-router-dom';
const staff = apiContainer.staff
const staffDetails = apiContainer.staffDetails

//GET--->
export async function getStaff(request) {
  try {
    const response = await apiReturnCallBack("GET", staff, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

//GET--->
export async function getStaffDetails(request) {
  try {
    const response = await apiReturnCallBack("GET", staffDetails, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//CREATE---->
export async function createStaff(request) {
  try {
    const response = await apiReturnCallBack("POST", staff, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

//UPDATE---->
export async function updateStaff(request, staffId) {
  try {
    const response = await apiReturnCallBack("PUT", staff + `/${staffId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    throw error;
  }
}

//DELETE---->
export async function deleteStaff(request, staffId) {
  try {
    const response = await apiReturnCallBack("PUT", staff + `-delete/${staffId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    throw error;
  }
}
