import { getLoanList } from '../../api/AddLoanApi';

// employee/reducers.ts
const initialState = {
    getAddLoanList: [],
    getLoanList: [],
    getLoanListDetails: [],
    createAddLoanData: null,
    createLoanPaymentData: null,
    updateAddLoanData: null,
    isLoading: false,
    errorMessage: null,
    getAddLoanSuccess: false,
    getAddLoanFailure: false,
    getLoanListSuccess: false,
    getLoanListFailure: false,
    createLoanPaymentSuccess: false,
    createLoanPaymentFailure: false,
    getLoanListDetailsSuccess: false,
    getLoanListDetailsFailure: false,
    createAddLoanSuccess: false,
    createAddLoanFailure: false,
    updateAddLoanSuccess: false,
    updateAddLoanFailure: false,
    deletePaymentHistorySuccess: false,
    deletePaymentHistoryFailure: false,
};

export default function addLoanReducer(state = initialState, action: any) {
    switch (action.type) {
        case 'GET_ADDLOAN_SUCCESS': {
            return {
                ...state,
                getAddLoanSuccess: true,
                getAddLoanList: action.payload.data.data,
                getAddLoanFailure: false,
            };
        }
        case 'GET_ADDLOAN_FAILURE': {
            return {
                ...state,
                getAddLoanFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                getAddLoanSuccess: false,
            };
        }
        case 'RESET_GET_ADDLOAN': {
            return {
                ...state,
                getAddLoanSuccess: false,
                getAddLoanFailure: false,
                getAddLoanList: [],
                errorMessage: null,
            };
        }
        case 'GET_LOAN_LIST_DETAILS_SUCCESS': {
            return {
                ...state,
                getLoanListDetailsSuccess: true,
                getLoanListDetails: action.payload.data.data,
                getLoanListDetailsFailure: false,
            };
        }
        case 'GET_LOAN_LIST_DETAILS_FAILURE': {
            return {
                ...state,
                getLoanListDetailsFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                getLoanListDetailsSuccess: false,
            };
        }
        case 'RESET_GET_LOAN_LIST_DETAILS': {
            return {
                ...state,
                getLoanListDetailsSuccess: false,
                getLoanListDetailsFailure: false,
                getLoanListDetails: [],
                errorMessage: null,
            };
        }
        case 'GET_LOAN_LIST_SUCCESS': {
            return {
                ...state,
                getLoanListSuccess: true,
                getLoanList: action.payload.data.data,
                getLoanListFailure: false,
            };
        }
        case 'GET_LOAN_LIST_FAILURE': {
            return {
                ...state,
                getLoanListFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                getLoanListSuccess: false,
            };
        }
        case 'RESET_GET_LOAN_LIST': {
            return {
                ...state,
                getLoanListSuccess: false,
                getLoanListFailure: false,
                getLoanList: [],
                errorMessage: null,
            };
        }
        case 'CREATE_LOAN_PAYMENT_SUCCESS': {
            return {
                ...state,
                createLoanPaymentSuccess: true,
                createLoanPaymentData: action.payload.data.data,
                createLoanPaymentFailure: false,
            };
        }
        case 'CREATE_LOAN_PAYMENT_FAILURE': {
            return {
                ...state,
                createLoanPaymentFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                createLoanPaymentSuccess: false,
            };
        }
        case 'RESET_CREATE_LOAN_PAYMENT': {
            return {
                ...state,
                createLoanPaymentSuccess: false,
                createLoanPaymentFailure: false,
                createLoanPaymentData: null,
                errorMessage: null,
            };
        }
        case 'CREATE_ADDLOAN_SUCCESS': {
            return {
                ...state,
                createAddLoanSuccess: true,
                createAddLoanData: action.payload.data.data,
                createAddLoanFailure: false,
            };
        }
        case 'CREATE_ADDLOAN_FAILURE': {
            return {
                ...state,
                createAddLoanFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                createAddLoanSuccess: false,
            };
        }
        case 'RESET_CREATE_ADDLOAN': {
            return {
                ...state,
                createAddLoanSuccess: false,
                createAddLoanFailure: false,
                createAddLoanData: null,
                errorMessage: null,
            };
        }

        case 'UPDATE_ADDLOAN_SUCCESS': {
            return {
                ...state,
                updateAddLoanSuccess: true,
                updateAddLoanData: action.payload.data.data,
                updateAddLoanFailure: false,
            };
        }
        case 'UPDATE_ADDLOAN_FAILURE': {
            return {
                ...state,
                updateAddLoanFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                updateAddLoanSuccess: false,
            };
        }
        case 'RESET_UPDATE_ADDLOAN': {
            return {
                ...state,
                updateAddLoanSuccess: false,
                updateAddLoanFailure: false,
                updateAddLoanData: null,
                errorMessage: null,
            };
        }

        case 'DELETE_PAYMENT_HISTORY_SUCCESS': {
            return {
                ...state,
                deletePaymentHistorySuccess: true,
                deletePaymentHistoryFailure: false,
            };
        }
        case 'DELETE_PAYMENT_HISTORY_FAILURE': {
            return {
                ...state,
                deletePaymentHistoryFailure: true,
                errorMessage: action.errorMessage.errorMessage,
                deletePaymentHistorySuccess: false,
            };
        }
        case 'RESET_DELETE_PAYMENT_HISTORY': {
            return {
                ...state,
                deletePaymentHistorySuccess: false,
                deletePaymentHistoryFailure: false,
                errorMessage: null,
            };
        }

        default: {
            return state;
        }
    }
}
