// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import { getSettingsCompanyInfo, updateSettingsCompanyInfo } from '../../api/SettingsApi'; // Adjust the path as needed
import {
    getSettingsSuccess,
    getSettingsFailure,
    updateSettingsSuccess,
    updateSettingsFailure,
} from './actions';

// Saga to handle fetching settingss
function* fetchSettingsSaga(action: any): Generator<any, any, any> {
    try {
        const data = yield call(getSettingsCompanyInfo, action.payload);
        yield put(getSettingsSuccess(data));
    } catch (error: any) {
        const errorMessage =
            error.response && error.response.data && error.response.data.message
                ? error.response.data.message
                : error.message
                ? error.message
                : 'An unexpected error occurred';

        yield put(getSettingsFailure(errorMessage));
    }
}

// // Saga to handle updating a settings
function* updateSettingsSaga(action: any): Generator<any, any, any> {
    try {
        const data = yield call(updateSettingsCompanyInfo, action.payload.data, action.payload.id);
        yield put(updateSettingsSuccess(data));
    } catch (error: any) {
        const errorMessage =
            error.response && error.response.data && error.response.data.message
                ? error.response.data.message
                : error.message
                ? error.message
                : 'An unexpected error occurred';

        yield put(updateSettingsFailure(errorMessage));
    }
}

export default function* settingsSaga() {
    yield takeEvery('GET_SETTINGS_REQUEST', fetchSettingsSaga);
    yield takeEvery('UPDATE_SETTINGS_REQUEST', updateSettingsSaga);
    // yield takeEvery('DELETE_SETTINGS_REQUEST', deleteSettingsSaga);
}
