// Staff Geolocations Actions
export const getStaffGeolocationsRequest = (params?: any) => ({
 type: 'GET_STAFF_GEOLOCATIONS_REQUEST',
 payload: params,
});

export const getStaffGeolocationsSuccess = (data: any) => ({
 type: 'GET_STAFF_GEOLOCATIONS_SUCCESS',
 payload: { data },
});

export const getStaffGeolocationsFailure = (errorMessage: string) => ({
 type: 'GET_STAFF_GEOLOCATIONS_FAILURE',
 errorMessage: { errorMessage },
});

