// employee/reducers.ts
const initialState = {
  getDashboardList: [],
  isLoading: false,
  errorMessage: null,
  getDashboardSuccess: false,
  getDashboardFailure: false,
};

export default function dashboardReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_DASHBOARD_SUCCESS": {
      return {
        ...state,
        getDashboardSuccess: true,
        getDashboardList: action.payload.data.data,
        getDashboardFailure: false,
      };
    }
    case "GET_DASHBOARD_FAILURE": {
      return {
        ...state,
        getDashboardFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getDashboardSuccess: false,
      };
    }
    case "RESET_GET_DASHBOARD": {
      return {
        ...state,
        getDashboardSuccess: false,
        getDashboardFailure: false,
        getDashboardList: [],
        errorMessage: null,
      };
    }

    default: {
      return state;
    }
  }
}
