import { call, put, takeEvery } from 'redux-saga/effects';
import { getNotification } from '../../api/NotificationApi'; // You'll need to create this API service
import {
  getNotificationSuccess,
  getNotificationFailure,
} from './action';

function* fetchNotificationSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getNotification, action.payload);
    yield put(getNotificationSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message 
      ? error.response.data.message 
      : error.message 
        ? error.message 
        : 'An unexpected error occurred';
    yield put(getNotificationFailure(errorMessage));
  }
}

export default function* notificationSaga() {
  yield takeEvery('GET_NOTIFICATION_REQUEST', fetchNotificationSaga);
}