import { apiReturnCallBack } from './ApiConfig';
import { Navigate } from 'react-router-dom';
import apiContainer from './apiContainer';
const visitPlaces = apiContainer.visitPlaces
//GET--->
export async function getVisitPlaces(request) {
  try {
    const response = await apiReturnCallBack("GET", visitPlaces, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//CREATE---->
export async function createVisitPlaces(request) {
  try {
    const response = await apiReturnCallBack("POST", visitPlaces, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//UPDATE---->
export async function updateVisitPlaces(request, visitPlacesId) {
  try {
    const response = await apiReturnCallBack("PUT", visitPlaces + `/${visitPlacesId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
