import { Navigate } from 'react-router-dom';
import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
const account = apiContainer.account
//GET--->
export async function getAccount(request) {
  try {
    const response = await apiReturnCallBack("GET", account, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//CREATE---->
export async function createAccount(request) {
  try {
    const response = await apiReturnCallBack("POST", account, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
//UPDATE---->
export async function updateAccount(request, accountId) {
  try {
    const response = await apiReturnCallBack("PUT", account + `/${accountId}`, request);
    const data = await response.json();
    if (!response.ok) {
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
