// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import {
    createAddLoan,
    createLoanPayment,
    deletePaymentHistory,
    getAddLoan,
    getLoanList,
    getLoanListDetails,
    updateAddLoan,
} from '../../api/AddLoanApi'; // Adjust the path as needed
import {
    getAddLoanSuccess,
    getAddLoanFailure,
    createAddLoanSuccess,
    createAddLoanFailure,
    updateAddLoanSuccess,
    updateAddLoanFailure,
    getLoanListDetailsSuccess,
    getLoanListDetailsFailure,
    createLoanPaymentSuccess,
    createLoanPaymentFailure,
    getLoanListSuccess,
    getLoanListFailure,
    deletePaymentHistoryFailure,
    deletePaymentHistorySuccess,
} from './actions';

// Saga to handle fetching addLoans
function* fetchAddLoanSaga(action: any): Generator<any, any, any> {
    try {
        const data = yield call(getAddLoan, action.payload);
        yield put(getAddLoanSuccess(data));
    } catch (error: any) {
        const errorMessage =
            error.response && error.response.data && error.response.data.message
                ? error.response.data.message
                : error.message
                ? error.message
                : 'An unexpected error occurred';
        yield put(getAddLoanFailure(errorMessage));
    }
}

