// // Saga to handle updating a addLoan
function* updateAddLoanSaga(action: any): Generator<any, any, any> {
    try {
        const data = yield call(updateAddLoan, action.payload.data, action.payload.id);
        yield put(updateAddLoanSuccess(data));
    } catch (error: any) {
        const errorMessage =
            error.response && error.response.data && error.response.data.message
                ? error.response.data.message
                : error.message
                ? error.message
                : 'An unexpected error occurred';

        yield put(updateAddLoanFailure(errorMessage));
    }
}

// // Saga to handle updating a addLoan
function* deletePaymentHistorySaga(action: any): Generator<any, any, any> {
    try {
        const data = yield call(deletePaymentHistory,  action.payload.data, action.payload.id);
        yield put(deletePaymentHistorySuccess(data));
    } catch (error: any) {
        yield put(deletePaymentHistoryFailure(error.message));
    }
}

export default function* addLoanSaga() {
    yield takeEvery('GET_ADDLOAN_REQUEST', fetchAddLoanSaga);
    yield takeEvery('GET_LOAN_LIST_REQUEST', fetchLoanListSaga);
    yield takeEvery('GET_LOAN_LIST_DETAILS_REQUEST', fetchLoanListDetailsSaga);
    yield takeEvery('CREATE_LOAN_PAYMENT_REQUEST', createLoanPaymentSaga);
    yield takeEvery('CREATE_ADDLOAN_REQUEST', createAddLoanSaga);
    yield takeEvery('UPDATE_ADDLOAN_REQUEST', updateAddLoanSaga);
    yield takeEvery('DELETE_PAYMENT_HISTORY_REQUEST', deletePaymentHistorySaga);
}
