//Get Reducer Call--->
export const getSettingDeductionRequest = (params?: any) => ({
    type: 'GET_SETTING_DEDUCTION_REQUEST',
    payload: params,
});

export const getSettingDeductionSuccess = (data: any) => ({
    type: 'GET_SETTING_DEDUCTION_SUCCESS',
    payload: { data },
});

export const getSettingDeductionFailure = (errorMessage: string) => ({
    type: 'GET_SETTING_DEDUCTION_FAILURE',
    errorMessage: { errorMessage },
});

export const resetGetSettingDeduction = () => ({
    type: 'RESET_GET_SETTING_DEDUCTION',
});

//Create Reducer Call--->
export const createSettingDeductionRequest = (data: any) => ({
    type: 'CREATE_SETTING_DEDUCTION_REQUEST',
    payload: data,
});

export const createSettingDeductionSuccess = (data: any) => ({
    type: 'CREATE_SETTING_DEDUCTION_SUCCESS',
    payload: { data },
});

export const createSettingDeductionFailure = (errorMessage: string) => ({
    type: 'CREATE_SETTING_DEDUCTION_FAILURE',
    errorMessage: { errorMessage },
});

export const resetCreateSettingDeduction = () => ({
    type: 'RESET_CREATE_SETTING_DEDUCTION',
});

//Update Reducer Call--->
export const updateSettingDeductionRequest = (data: any, id: string) => ({
    type: 'UPDATE_SETTING_DEDUCTION_REQUEST',
    payload: { data, id },
});

export const updateSettingDeductionSuccess = (data: any) => ({
    type: 'UPDATE_SETTING_DEDUCTION_SUCCESS',
    payload: { data },
});

export const updateSettingDeductionFailure = (errorMessage: string) => ({
    type: 'UPDATE_SETTING_DEDUCTION_FAILURE',
    errorMessage: { errorMessage },
});

export const resetUpdateSettingDeduction = () => ({
    type: 'RESET_UPDATE_SETTING_DEDUCTION',
});
