// AllLiveMap.js
import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { GoogleMap, Marker, InfoWindow, useLoadScript } from '@react-google-maps/api';
import {
 MapPin,
 Navigation,
 Battery,
 Wifi,
 Clock,
 Map,
 Image as ImageIcon,
 ZoomIn,
 ZoomOut,
 Target,
 Layers,
 Maximize2,
 Minimize2,
 Users,
 User,
 Filter,
 RefreshCw,
 Eye,
 EyeOff,
 AlertCircle,
 Building,
 Activity,
 Circle,
 Phone,
 Mail,
 Calendar,
 Shield,
 Car,
 Building2,
 WifiOff,
 UserX,
 Users as UsersIcon,
 MapPinOff,
} from 'lucide-react';
import { baseURL } from '../../api/ApiConfig';
import './AllLiveMap.css';

const resolveImageUrl = (url) => (url && !url.startsWith('http') ? baseURL + url : url);

const mapContainerStyle = {
 width: '100%',
 height: '100%',
 minHeight: '600px',
};

// Move libraries array outside component
const LIBRARIES = ['places', 'geometry'];

// ActionType based icons with custom SVG-like icons
const ACTION_TYPE_ICONS = {
 // Moving - Bike icon (like 🚴)
 moving: {
  // Bike emoji style
  path:
   'M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 14.5c0 .83-.67 1.5-1.5 1.5S8 17.33 8 16.5 8.67 15 9.5 15s1.5.67 1.5 1.5zm6 0c0 .83-.67 1.5-1.5 1.5s-1.5-.67-1.5-1.5.67-1.5 1.5-1.5 1.5.67 1.5 1.5zM7.82 12L12 7.82 16.18 12 12 16.18 7.82 12z',
  fillColor: '#10B981',
  fillOpacity: 0.9,
  strokeColor: '#FFFFFF',
  strokeWeight: 2,
  scale: 1.2,
  anchor: { x: 12, y: 12 },
 },
 'not moving': {
  // Chair emoji style
  path:
   'M19 7h-3V5.5A2.5 2.5 0 0 0 13.5 3h-3A2.5 2.5 0 0 0 8 5.5V7H5c-1.1 0-2 .9-2 2v5c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V9c0-1.1-.9-2-2-2zm-4 2v2H9V9h6zm-6-3.5c0-.28.22-.5.5-.5h3c.28 0 .5.22.5.5V7H9V5.5zM19 14H5V9h2v2h10V9h2v5z',
  fillColor: '#3B82F6',
  fillOpacity: 0.9,
  strokeColor: '#FFFFFF',
  strokeWeight: 2,
  scale: 1.2,
  anchor: { x: 12, y: 12 },
 },
 offline: {
  // No wifi emoji style
  path:
   'M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm0-14c-3.31 0-6 2.69-6 6h2c0-2.21 1.79-4 4-4s4 1.79 4 4h2c0-3.31-2.69-6-6-6z',
  fillColor: '#EF4444',
  fillOpacity: 0.9,
  strokeColor: '#FFFFFF',
  strokeWeight: 2,
  scale: 1.2,
  anchor: { x: 12, y: 12 },
 },
 meeting: {
  // Speech bubbles emoji style
  path:
   'M20 2H4c-1.1 0-1.99.9-1.99 2L2 22l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM6 9h12v2H6V9zm8 5H6v-2h8v2zm4-6H6V6h12v2z',
  fillColor: '#8B5CF6',
  fillOpacity: 0.9,
  strokeColor: '#FFFFFF',
  strokeWeight: 2,
  scale: 1.2,
  anchor: { x: 12, y: 12 },
 },
 default: {
  // Person emoji style
  path:
   'M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08 1.99 0 5.97 1.09 6 3.08-1.29 1.94-3.5 3.22-6 3.22z',
  fillColor: '#F59E0B',
  fillOpacity: 0.9,
  strokeColor: '#FFFFFF',
  strokeWeight: 2,
  scale: 1.2,
  anchor: { x: 12, y: 12 },
 },
};

// ActionType colors
const ACTION_TYPE_COLORS = {
 moving: '#10B981', // Green
 'not moving': '#3B82F6', // Blue
 offline: '#6B7280', // Gray
 meeting: '#8B5CF6', // Purple
 default: '#F59E0B', // Orange
};

// ActionType labels
const ACTION_TYPE_LABELS = {
 moving: 'Moving',
 'not moving': 'Stationary',
 offline: 'Offline',
 meeting: 'In Meeting',
 default: 'Active',
};

// ActionType icons for UI
const ACTION_TYPE_UI_ICONS = {
 moving: Car,
 'not moving': User,
 offline: WifiOff,
 meeting: UsersIcon,
 default: User,
};

export default function AllLiveMap({ data = [], onEmployeeClick }) {
 console.log('data');
 console.log(data);
 const { isLoaded, loadError } = useLoadScript({
  googleMapsApiKey: 'AIzaSyD1Uvzt4qmx6O7DcUf0gH3DfrLssx_ARfc',
  libraries: LIBRARIES,
 });

 const [selectedEmployee, setSelectedEmployee] = useState(null);
 const [mapRef, setMapRef] = useState(null);
 const [zoom, setZoom] = useState(12);
 const [mapType, setMapType] = useState('roadmap');
 const [showLegend, setShowLegend] = useState(true);
 const [filters, setFilters] = useState({
  actionType: 'all',
  showOffline: true,
 });
 const [autoRefresh, setAutoRefresh] = useState(false);
 const [center, setCenter] = useState({ lat: 12.9716, lng: 77.5946 });
 const [fullPageMode, setFullPageMode] = useState(false);
 const [isFullscreen, setIsFullscreen] = useState(false);

 const centerChangedRef = useRef(false);
 const fitBoundsTriggeredRef = useRef(false);

 // Process and group employee data
 const { employees, stats } = useMemo(() => {
  if (!Array.isArray(data) || data.length === 0) {
   return { employees: [], stats: {} };
  }

  const employeesList = [];
  const actionTypeCount = {
   moving: 0,
   'not moving': 0,
   offline: 0,
   meeting: 0,
   default: 0,
  };

  data.forEach((item, index) => {
   if (!item || !item.records) return;

   const records = item.records;
   const geoLocations = records.geoLocation || [];

   if (geoLocations.length > 0) {
    const latestLocation = geoLocations[geoLocations.length - 1];

    let lat, lng;

    if (latestLocation.latitude && latestLocation.longitude) {
     lat = parseFloat(latestLocation.latitude);
     lng = parseFloat(latestLocation.longitude);
    } else if (latestLocation.coordinates && Array.isArray(latestLocation.coordinates)) {
     lng = parseFloat(latestLocation.coordinates[0]);
     lat = parseFloat(latestLocation.coordinates[1]);
    }

    if (!isNaN(lat) && !isNaN(lng)) {
     // Determine action type
     const actionType = latestLocation.actionType?.toLowerCase() || 'default';
     const validActionType = ACTION_TYPE_ICONS[actionType] ? actionType : 'default';

     const employee = {
      id: records.employeeId || index,
      empCode: records.empCode || `EMP-${index}`,
      empName: records.empName || 'Unknown Employee',
      department: records.subDomain || 'General',
      actionType: validActionType,
      position: { lat, lng },
      geoLocations,
      latestLocation,
      subDomain: records.subDomain,
      shiftWithException: records.shiftWithException || 'No Shift',
      attendanceDate: records.attendanceDate,
      totalDistance: records.totalDistance || 0,
      battery: latestLocation.battery || 'N/A',
      networkStatus: latestLocation.networkStatus || 'N/A',
      speed: latestLocation.speed || '0',
      image: latestLocation.imageUrl || latestLocation.image,
      createdAt: latestLocation.createdAt,
      color: ACTION_TYPE_COLORS[validActionType],
      isMoving: validActionType === 'moving',
     };

     employeesList.push(employee);
     actionTypeCount[validActionType] = (actionTypeCount[validActionType] || 0) + 1;
    }
   }
  });

  return {
   employees: employeesList,
   stats: {
    total: employeesList.length,
    ...actionTypeCount,
    withImages: employeesList.filter((e) => e.image).length,
    moving: employeesList.filter((e) => e.isMoving).length,
   },
  };
 }, [data]);

 // Filter employees based on filters
 const filteredEmployees = useMemo(() => {
  return employees.filter((emp) => {
   if (filters.actionType !== 'all' && emp.actionType !== filters.actionType) return false;
   if (!filters.showOffline && emp.actionType === 'offline') return false;
   return true;
  });
 }, [employees, filters]);

 // Calculate map bounds to fit all employees
 const fitBounds = useCallback(() => {
  if (mapRef && filteredEmployees.length > 0 && !fitBoundsTriggeredRef.current) {
   fitBoundsTriggeredRef.current = true;

   const bounds = new window.google.maps.LatLngBounds();
   filteredEmployees.forEach((emp) => bounds.extend(emp.position));
   mapRef.fitBounds(bounds);

   const boundsCenter = bounds.getCenter();
   const newCenter = { lat: boundsCenter.lat(), lng: boundsCenter.lng() };

   if (Math.abs(newCenter.lat - center.lat) > 0.0001 || Math.abs(newCenter.lng - center.lng) > 0.0001) {
    setCenter(newCenter);
   }

   setTimeout(() => {
    fitBoundsTriggeredRef.current = false;
   }, 1000);
  }
 }, [mapRef, filteredEmployees, center]);

 // Auto-refresh effect
 useEffect(() => {
  let interval;
  if (autoRefresh) {
   interval = setInterval(() => {
    console.log('Refreshing employee locations...');
   }, 30000);
  }
  return () => {
   if (interval) clearInterval(interval);
  };
 }, [autoRefresh]);

 // Get marker icon based on actionType
 const getMarkerIcon = useCallback((actionType, isSelected = false) => {
  if (!window.google) return null;

  const iconConfig = ACTION_TYPE_ICONS[actionType] || ACTION_TYPE_ICONS.default;

  // If selected, make the marker larger
  const scale = isSelected ? 2 : iconConfig.scale;

  return {
   ...iconConfig,
   scale,
  };
 }, []);

 // Get marker label for employee name abbreviation
 const getMarkerLabel = useCallback((empName) => {
  if (!window.google) return null;

  // Get first letter of first name and last name
  const nameParts = empName.split(' ');
  let abbreviation = '';

  if (nameParts.length === 1) {
   abbreviation = nameParts[0].charAt(0).toUpperCase();
  } else {
   abbreviation = (nameParts[0].charAt(0) + nameParts[nameParts.length - 1].charAt(0)).toUpperCase();
  }

  return {
   text: abbreviation,
   color: '#FFFFFF',
   fontSize: '10px',
   fontWeight: 'bold',
   className: 'marker-label',
  };
 }, []);

 // Format time
 const formatTime = useCallback((timestamp) => {
  if (!timestamp) return 'N/A';
  try {
   const date = new Date(Number(timestamp));
   return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  } catch (error) {
   return 'Invalid time';
  }
 }, []);

 // Handle center changed
 const handleCenterChanged = useCallback(() => {
  if (mapRef && !centerChangedRef.current) {
   centerChangedRef.current = true;

   const currentCenter = mapRef.getCenter();
   if (currentCenter) {
    const newCenter = { lat: currentCenter.lat(), lng: currentCenter.lng() };

    if (Math.abs(newCenter.lat - center.lat) > 0.0001 || Math.abs(newCenter.lng - center.lng) > 0.0001) {
     setCenter(newCenter);
    }
   }

   setTimeout(() => {
    centerChangedRef.current = false;
   }, 500);
  }
 }, [mapRef, center]);

 // Handle map load
 const handleMapLoad = useCallback(
  (map) => {
   console.log('Google Map loaded');
   setMapRef(map);

   setTimeout(() => {
    if (filteredEmployees.length > 0) {
     fitBounds();
    }
   }, 500);
  },
  [filteredEmployees, fitBounds]
 );

 // Handle zoom changed
 const handleZoomChanged = useCallback(() => {
  if (mapRef) {
   setZoom(mapRef.getZoom());
  }
 }, [mapRef]);

 // Toggle map type
 const toggleMapType = useCallback(() => {
  const types = ['roadmap', 'satellite', 'hybrid', 'terrain'];
  const currentIndex = types.indexOf(mapType);
  const nextType = types[(currentIndex + 1) % types.length];
  setMapType(nextType);
 }, [mapType]);

 // Toggle full page mode
 const toggleFullPageMode = useCallback(() => {
  const newFullPageMode = !fullPageMode;
  setFullPageMode(newFullPageMode);
  setIsFullscreen(newFullPageMode);

  if (newFullPageMode) {
   document.body.style.overflow = 'hidden';
   // Fit bounds after entering full screen
   setTimeout(() => {
    if (mapRef && filteredEmployees.length > 0) {
     fitBounds();
    }
   }, 100);
  } else {
   document.body.style.overflow = '';
  }
 }, [fullPageMode, mapRef, filteredEmployees, fitBounds]);

 // Handle escape key
 useEffect(() => {
  const handleEscape = (e) => {
   if (e.key === 'Escape' && fullPageMode) {
    toggleFullPageMode();
   }
  };

  window.addEventListener('keydown', handleEscape);
  return () => {
   window.removeEventListener('keydown', handleEscape);
   if (fullPageMode) {
    document.body.style.overflow = '';
   }
  };
 }, [fullPageMode, toggleFullPageMode]);

 // Handle fullscreen change
 useEffect(() => {
  const handleFullscreenChange = () => {
   if (!document.fullscreenElement && fullPageMode) {
    toggleFullPageMode();
   }
  };

  document.addEventListener('fullscreenchange', handleFullscreenChange);
  return () => {
   document.removeEventListener('fullscreenchange', handleFullscreenChange);
  };
 }, [fullPageMode, toggleFullPageMode]);

 if (loadError) {
  return (
   <div className="map-error">
    <div className="error-content">
     <AlertCircle size={48} className="error-icon" />
     <h3>Error Loading Map</h3>
     <p>Unable to load Google Maps. Please check your internet connection.</p>
    </div>
   </div>
  );
 }

 if (!isLoaded) {
  return (
   <div className="map-loading">
    <div className="spinner"></div>
    <p>Loading Google Maps...</p>
   </div>
  );
 }

 return (
  <>
   {fullPageMode && <div className="full-page-overlay"></div>}

   <div className={`live-map-wrapper ${fullPageMode ? 'full-page-mode' : ''}`}>
    {/* Full Page Map View */}
    {fullPageMode && (
     <div className="full-page-map">
      <GoogleMap
       mapContainerStyle={{
        width: '100vw',
        height: '100vh',
        position: 'fixed',
        top: 0,
        left: 0,
       }}
       zoom={zoom}
       center={center}
       options={{
        streetViewControl: true,
        mapTypeControl: true,
        fullscreenControl: false,
        zoomControl: true,
        mapTypeId: mapType,
        styles: [
         {
          featureType: 'poi',
          elementType: 'labels',
          stylers: [{ visibility: 'off' }],
         },
        ],
       }}
       onLoad={handleMapLoad}
       onZoomChanged={handleZoomChanged}
       onCenterChanged={handleCenterChanged}>
       {/* Display markers with employee names */}
       {filteredEmployees.map((employee) => (
        <React.Fragment key={employee.id}>
         <Marker
          position={employee.position}
          onClick={() => {
           setSelectedEmployee(employee);
           if (onEmployeeClick) {
            onEmployeeClick(employee);
           }
          }}
          icon={getMarkerIcon(employee.actionType, selectedEmployee?.id === employee.id)}
          label={getMarkerLabel(employee.empName)}
          animation={selectedEmployee?.id === employee.id ? window.google.maps.Animation.BOUNCE : null}
         />

         {/* Add pulse circle for moving employees */}
         {employee.actionType === 'moving' && (
          <Circle
           center={employee.position}
           radius={50} // 50 meters radius
           options={{
            fillColor: '#10B981',
            fillOpacity: 0.1,
            strokeColor: '#10B981',
            strokeOpacity: 0.3,
            strokeWeight: 1,
           }}
          />
         )}
        </React.Fragment>
       ))}

       {/* InfoWindow for selected employee */}
       {selectedEmployee && (
        <InfoWindow position={selectedEmployee.position} onCloseClick={() => setSelectedEmployee(null)}>
         <div className="info-window-content">
          <div className="info-header">
           <div className="marker-badge" style={{ backgroundColor: ACTION_TYPE_COLORS[selectedEmployee.actionType] }}>
            {(() => {
             const IconComponent = ACTION_TYPE_UI_ICONS[selectedEmployee.actionType];
             return <IconComponent size={16} />;
            })()}
           </div>
           <div>
            <h4>{selectedEmployee.empName}</h4>
            <p style={{ color: '#6B7280', fontSize: '12px' }}>
             {selectedEmployee.empCode} • {selectedEmployee.subDomain}
            </p>
           </div>
          </div>

          <div className="info-grid">
           <div className="info-row">
            <Clock size={14} />
            <span>Last Update: {formatTime(selectedEmployee.createdAt)}</span>
           </div>

           <div className="info-row">
            <MapPin size={14} />
            <span className="address">
             {selectedEmployee.latestLocation.coordinatesPoints ||
              `${selectedEmployee.position.lat.toFixed(6)}, ${selectedEmployee.position.lng.toFixed(6)}`}
            </span>
           </div>

           <div className="info-row">
            <Activity size={14} />
            <span>
             Status:
             <strong
              style={{
               color: ACTION_TYPE_COLORS[selectedEmployee.actionType],
               marginLeft: '4px',
              }}>
              {ACTION_TYPE_LABELS[selectedEmployee.actionType].toUpperCase()}
             </strong>
            </span>
           </div>

           <div className="info-row">
            <Navigation size={14} />
            <span>Speed: {selectedEmployee.speed} km/h</span>
           </div>

           <div className="info-row">
            <Battery size={14} />
            <span>Battery: {selectedEmployee.battery}</span>
           </div>

           <div className="info-row">
            <Wifi size={14} />
            <span>Network: {selectedEmployee.networkStatus}</span>
           </div>

           <div className="info-row">
            <Map size={14} />
            <span>Total Distance: {selectedEmployee.totalDistance} km</span>
           </div>

           <div className="info-row">
            <Building size={14} />
            <span>Shift: {selectedEmployee.shiftWithException}</span>
           </div>
          </div>

          {selectedEmployee.image && selectedEmployee.image !== 'N/A' && (
           <div className="image-section">
            <button onClick={() => window.open(resolveImageUrl(selectedEmployee.image), '_blank')} className="view-image-btn">
             <ImageIcon size={14} />
             View Location Image
            </button>
           </div>
          )}

          <div className="location-actions">
           <button
            onClick={() => {
             const url = `https://www.google.com/maps?q=${selectedEmployee.position.lat},${selectedEmployee.position.lng}`;
             window.open(url, '_blank');
            }}
            className="location-btn">
            <Map size={14} />
            Open in Google Maps
           </button>
          </div>
         </div>
        </InfoWindow>
       )}
      </GoogleMap>

      {/* Full page controls */}
      <div className="full-page-controls">
       <div className="control-group">
        <button onClick={() => mapRef && mapRef.setZoom(mapRef.getZoom() + 1)} className="control-btn" title="Zoom In">
         <ZoomIn size={20} />
        </button>
        <button onClick={() => mapRef && mapRef.setZoom(mapRef.getZoom() - 1)} className="control-btn" title="Zoom Out">
         <ZoomOut size={20} />
        </button>
        <button onClick={fitBounds} className="control-btn" title="Fit All Employees">
         <Target size={20} />
        </button>
        <button onClick={toggleMapType} className="control-btn" title="Change Map Type">
         <Layers size={20} />
        </button>
        <button onClick={toggleFullPageMode} className="control-btn exit-fullscreen-btn" title="Exit Full Screen">
         <Minimize2 size={20} />
        </button>
       </div>

       <div className="full-page-stats">
        <div className="stat-badge">
         <Users size={14} />
         <span>{stats.total} Employees</span>
        </div>
        <div className="stat-badge">
         <Car size={14} />
         <span>{stats.moving || 0} Moving</span>
        </div>
        <div className="stat-badge">
         <MapPin size={14} />
         <span>Zoom: {zoom}</span>
        </div>
       </div>
      </div>
     </div>
    )}

    {/* Normal Map View */}
    {!fullPageMode && (
     <div className="normal-map-container">
      <div className="map-header">
       <div>
        <h3>Employee Live Tracking Map</h3>
        <p style={{ fontSize: '12px', opacity: 0.8, marginTop: '4px' }}>
         Tracking {stats.total} employees • {stats.moving || 0} moving • {stats.meeting || 0} in meetings
        </p>
       </div>
       <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
        {filteredEmployees.length > 0 && (
         <button onClick={fitBounds} className="fullscreen-btn" title="Fit All Employees">
          <Target size={16} />
          <span>Fit All</span>
         </button>
        )}
        <button
         onClick={() => setAutoRefresh(!autoRefresh)}
         className={`fullscreen-btn ${autoRefresh ? 'active' : ''}`}
         title="Auto Refresh"
         style={{ background: autoRefresh ? '#10B981' : 'rgba(255,255,255,0.2)' }}>
         <RefreshCw size={16} className={autoRefresh ? 'spinning' : ''} />
         <span>Auto Refresh</span>
        </button>
        <button onClick={toggleFullPageMode} className="fullscreen-btn" title="Full Screen Map">
         <Maximize2 size={20} />
         <span>Full Screen</span>
        </button>
       </div>
      </div>

      <div className="map-content">
       {/* Map Controls */}
       <div className="map-controls">
        <button onClick={() => mapRef && mapRef.setZoom(mapRef.getZoom() + 1)} className="control-btn" title="Zoom In">
         <ZoomIn size={20} />
        </button>
        <button onClick={() => mapRef && mapRef.setZoom(mapRef.getZoom() - 1)} className="control-btn" title="Zoom Out">
         <ZoomOut size={20} />
        </button>
        {filteredEmployees.length > 0 && (
         <button onClick={fitBounds} className="control-btn" title="Fit All Employees">
          <Target size={20} />
         </button>
        )}
        <button onClick={toggleMapType} className="control-btn" title="Change Map Type">
         <Layers size={20} />
        </button>
        <button
         onClick={() => setFilters({ ...filters, showOffline: !filters.showOffline })}
         className={`control-btn ${!filters.showOffline ? 'active' : ''}`}
         title="Toggle Offline Employees">
         {filters.showOffline ? <Eye size={20} /> : <EyeOff size={20} />}
        </button>
       </div>

       {/* Filters Panel */}
       {filteredEmployees.length > 0 && (
        <div className="filters-panel">
         <div className="filters-header">
          <Filter size={16} />
          <span>Filters</span>
         </div>
         <div className="filter-group">
          <label>Status:</label>
          <select
           value={filters.actionType}
           onChange={(e) => setFilters({ ...filters, actionType: e.target.value })}
           className="filter-select">
           <option value="all">All Status</option>
           <option value="moving">Moving</option>
           <option value="not moving">Stationary</option>
           <option value="meeting">In Meeting</option>
           <option value="offline">Offline</option>
          </select>
         </div>
         <div className="filter-stats">
          <span>
           Showing {filteredEmployees.length} of {employees.length} employees
          </span>
         </div>
        </div>
       )}

       {/* Legend Panel */}
       {showLegend && employees.length > 0 && (
        <div className="legend-panel">
         <div className="legend-header">
          <h5>
           <Map size={16} />
           <span>Status Legend</span>
          </h5>
          <button className="legend-toggle-btn" onClick={() => setShowLegend(!showLegend)} title="Hide Legend">
           ×
          </button>
         </div>

         <div className="legend-items">
          {Object.entries(ACTION_TYPE_LABELS).map(([actionType, label]) => (
           <div key={actionType} className="legend-item">
            <div className="legend-color" style={{ backgroundColor: ACTION_TYPE_COLORS[actionType] }}></div>
            <span>{label}</span>
            <span className="legend-count">{stats[actionType] || 0}</span>
           </div>
          ))}
         </div>

         <div className="legend-stats">
          <div className="legend-stat">
           <span>Total Employees:</span>
           <strong>{stats.total}</strong>
          </div>
          <div className="legend-stat">
           <span>Zoom Level:</span>
           <strong>{zoom}</strong>
          </div>
         </div>
        </div>
       )}

       {/* Employee List Panel */}
       {filteredEmployees.length > 0 && (
        <div className="employee-list-panel">
         <div className="employee-list-header">
          <Users size={16} />
          <span>Employees ({filteredEmployees.length})</span>
         </div>
         <div className="employee-list">
          {filteredEmployees.slice(0, 5).map((emp) => (
           <div
            key={emp.id}
            className={`employee-item ${selectedEmployee?.id === emp.id ? 'selected' : ''}`}
            onClick={() => {
             setSelectedEmployee(emp);
             if (onEmployeeClick) {
              onEmployeeClick(emp);
             }
            }}
            style={{ borderLeftColor: ACTION_TYPE_COLORS[emp.actionType] }}>
            <div className="employee-avatar" style={{ backgroundColor: ACTION_TYPE_COLORS[emp.actionType] }}>
             {emp.empName.charAt(0)}
            </div>
            <div className="employee-details">
             <div className="employee-name">{emp.empName}</div>
             <div className="employee-code">{emp.empCode}</div>
             <div className="employee-status" style={{ color: ACTION_TYPE_COLORS[emp.actionType] }}>
              {ACTION_TYPE_LABELS[emp.actionType].toUpperCase()}
             </div>
            </div>
            <div className="employee-location">
             <Navigation size={12} />
             <span>{emp.speed} km/h</span>
            </div>
           </div>
          ))}
          {filteredEmployees.length > 5 && (
           <div className="employee-more">+ {filteredEmployees.length - 5} more employees</div>
          )}
         </div>
        </div>
       )}

       {/* Google Map */}
       <GoogleMap
        mapContainerStyle={mapContainerStyle}
        zoom={zoom}
        center={center}
        options={{
         streetViewControl: false,
         mapTypeControl: false,
         fullscreenControl: false,
         zoomControl: false,
         mapTypeId: mapType,
         styles: [
          {
           featureType: 'poi',
           elementType: 'labels',
           stylers: [{ visibility: 'off' }],
          },
         ],
        }}
        onLoad={handleMapLoad}
        onZoomChanged={handleZoomChanged}
        onCenterChanged={handleCenterChanged}>
        {/* Display markers with employee names */}
        {filteredEmployees.map((employee) => (
         <React.Fragment key={employee.id}>
          <Marker
           position={employee.position}
           onClick={() => setSelectedEmployee(employee)}
           icon={getMarkerIcon(employee.actionType, selectedEmployee?.id === employee.id)}
           label={getMarkerLabel(employee.empName)}
           animation={selectedEmployee?.id === employee.id ? window.google.maps.Animation.BOUNCE : null}
          />

          {/* Add pulse circle for moving employees */}
          {employee.actionType === 'moving' && (
           <Circle
            center={employee.position}
            radius={50} // 50 meters radius
            options={{
             fillColor: '#10B981',
             fillOpacity: 0.1,
             strokeColor: '#10B981',
             strokeOpacity: 0.3,
             strokeWeight: 1,
            }}
           />
          )}
         </React.Fragment>
        ))}

        {/* InfoWindow for selected employee */}
        {selectedEmployee && (
         <InfoWindow position={selectedEmployee.position} onCloseClick={() => setSelectedEmployee(null)}>
          <div className="info-window-content">
           <div className="info-header">
            <div className="marker-badge" style={{ backgroundColor: ACTION_TYPE_COLORS[selectedEmployee.actionType] }}>
             {(() => {
              const IconComponent = ACTION_TYPE_UI_ICONS[selectedEmployee.actionType];
              return <IconComponent size={16} />;
             })()}
            </div>
            <div>
             <h4>{selectedEmployee.empName}</h4>
             <p style={{ color: '#6B7280', fontSize: '12px' }}>
              {selectedEmployee.empCode} • {selectedEmployee.subDomain}
             </p>
            </div>
           </div>

           <div className="info-grid">
            <div className="info-row">
             <Clock size={14} />
             <span>Last Update: {formatTime(selectedEmployee.createdAt)}</span>
            </div>

            <div className="info-row">
             <MapPin size={14} />
             <span className="address">
              {selectedEmployee.latestLocation.coordinatesPoints ||
               `${selectedEmployee.position.lat.toFixed(6)}, ${selectedEmployee.position.lng.toFixed(6)}`}
             </span>
            </div>

            <div className="info-row">
             <Activity size={14} />
             <span>
              Status:
              <strong
               style={{
                color: ACTION_TYPE_COLORS[selectedEmployee.actionType],
                marginLeft: '4px',
               }}>
               {ACTION_TYPE_LABELS[selectedEmployee.actionType].toUpperCase()}
              </strong>
             </span>
            </div>

            <div className="info-row">
             <Navigation size={14} />
             <span>Speed: {selectedEmployee.speed} km/h</span>
            </div>

            <div className="info-row">
             <Battery size={14} />
             <span>Battery: {selectedEmployee.battery}</span>
            </div>

            <div className="info-row">
             <Wifi size={14} />
             <span>Network: {selectedEmployee.networkStatus}</span>
            </div>

            <div className="info-row">
             <Map size={14} />
             <span>Total Distance: {selectedEmployee.totalDistance} km</span>
            </div>

            <div className="info-row">
             <Building size={14} />
             <span>Shift: {selectedEmployee.shiftWithException}</span>
            </div>
           </div>

           {selectedEmployee.image && selectedEmployee.image !== 'N/A' && (
            <div className="image-section">
             <button onClick={() => window.open(resolveImageUrl(selectedEmployee.image), '_blank')} className="view-image-btn">
              <ImageIcon size={14} />
              View Location Image
             </button>
            </div>
           )}

           <div className="location-actions">
            <button
             onClick={() => {
              const url = `https://www.google.com/maps?q=${selectedEmployee.position.lat},${selectedEmployee.position.lng}`;
              window.open(url, '_blank');
             }}
             className="location-btn">
             <Map size={14} />
             Open in Google Maps
            </button>
           </div>
          </div>
         </InfoWindow>
        )}
       </GoogleMap>
      </div>
     </div>
    )}
   </div>
  </>
 );
}
