// App.js
import React from "react";
import AllLiveMap from "./AllLiveMap";
import employeeData from "./sample copy.json";
import LiveMap from "./LiveMap";
import myJson from "./sample.json";

function App() {
  return (
    <div style={{ height: '100vh', padding: '20px' }}>
      <h1>Employee Live Tracking Dashboard</h1>
      <div style={{ height: 'calc(100vh - 80px)', marginTop: '20px' }}>
        <AllLiveMap data={employeeData.data} />
      </div>
    </div>
  );
}

export default App;