// employee/reducers.ts
const initialState = {
  getAccountList: [],
  createAccountData: null,
  updateAccountData: null,
  isLoading: false,
  errorMessage: null,
  getAccountSuccess: false,
  getAccountFailure: false,
  createAccountSuccess: false,
  createAccountFailure: false,
  updateAccountSuccess: false,
  updateAccountFailure: false,
  deleteAccountSuccess: false,
  deleteAccountFailure: false,
};

export default function accountReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_ACCOUNT_SUCCESS": {
      return {
        ...state,
        getAccountSuccess: true,
        getAccountList: action.payload.data.data,
        getAccountFailure: false,
      };
    }
    case "GET_ACCOUNT_FAILURE": {
      return {
        ...state,
        getAccountFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getAccountSuccess: false,
      };
    }
    case "RESET_GET_ACCOUNT": {
      return {
        ...state,
        getAccountSuccess: false,
        getAccountFailure: false,
        getAccountList: [],
        errorMessage: null,
      };
    }

    case "CREATE_ACCOUNT_SUCCESS": {
      return {
        ...state,
        createAccountSuccess: true,
        createAccountData: action.payload.data.data,
        createAccountFailure: false,
      };
    }
    case "CREATE_ACCOUNT_FAILURE": {
      return {
        ...state,
        createAccountFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        createAccountSuccess: false,
      };
    }
    case "RESET_CREATE_ACCOUNT": {
      return {
        ...state,
        createAccountSuccess: false,
        createAccountFailure: false,
        createAccountData: null,
        errorMessage: null,
      };
    }

    case "UPDATE_ACCOUNT_SUCCESS": {
      return {
        ...state,
        updateAccountSuccess: true,
        updateAccountData: action.payload.data.data,
        updateAccountFailure: false,
      };
    }
    case "UPDATE_ACCOUNT_FAILURE": {
      return {
        ...state,
        updateAccountFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updateAccountSuccess: false,
      };
    }
    case "RESET_UPDATE_ACCOUNT": {
      return {
        ...state,
        updateAccountSuccess: false,
        updateAccountFailure: false,
        updateAccountData: null,
        errorMessage: null,
      };
    }

    case "DELETE_ACCOUNT_SUCCESS": {
      return {
        ...state,
        deleteAccountSuccess: true,
        deleteAccountFailure: false,
      };
    }
    case "DELETE_ACCOUNT_FAILURE": {
      return {
        ...state,
        deleteAccountFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        deleteAccountSuccess: false,
      };
    }
    case "RESET_DELETE_ACCOUNT": {
      return {
        ...state,
        deleteAccountSuccess: false,
        deleteAccountFailure: false,
        errorMessage: null,
      };
    }

    default: {
      return state;
    }
  }
}
