//Get Reducer Call--->
export const getSettingsRequest = (params?: any) => ({
  type: 'GET_SETTINGS_REQUEST',
  payload: params,
});

export const getSettingsSuccess = (data: any) => ({
  type: 'GET_SETTINGS_SUCCESS',
  payload: { data },
});

export const getSettingsFailure = (errorMessage: string) => ({
  type: 'GET_SETTINGS_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetSettings = () => ({
  type: 'RESET_GET_SETTINGS',
});

//Update Reducer Call--->
export const updateSettingsRequest = ( data: any, id: string) => ({
  type: 'UPDATE_SETTINGS_REQUEST',
  payload: { data, id },
});

export const updateSettingsSuccess = (data: any) => ({
  type: 'UPDATE_SETTINGS_SUCCESS',
  payload: { data },
});

export const updateSettingsFailure = (errorMessage: string) => ({
  type: 'UPDATE_SETTINGS_FAILURE',
  errorMessage: { errorMessage },
});

export const resetUpdateSettings = () => ({
  type: 'RESET_UPDATE_SETTINGS',
});