// LiveMap.js
import React, { useState, useMemo, useCallback } from 'react';
import { GoogleMap, Marker, Polyline, InfoWindow, useLoadScript, Circle } from '@react-google-maps/api';
import {
  MapPin,
  Navigation,
  Battery,
  Wifi,
  Clock,
  Map,
  Image as ImageIcon,
  ZoomIn,
  ZoomOut,
  Target,
  Layers,
  Compass,
  Maximize2,
  Minimize2,
} from 'lucide-react';
import img from '../../assets/images/man.png';
import { baseURL } from '../../api/ApiConfig';
import './LiveMap.css';

const resolveImageUrl = (url) => (url && !url.startsWith('http') ? baseURL + url : url);

const mapContainerStyle = {
  width: '100%',
  height: '100%',
  minHeight: '600px',
};

// Enhanced marker icons with better visuals
const MARKER_ICONS = {
  'Punch In-Tracker': {
    url: 'http://maps.google.com/mapfiles/ms/icons/green-dot.png',
    size: { width: 90, height: 90 },
    label: 'PI',
  },
  'Punch Out-Tracker': {
    url: 'http://maps.google.com/mapfiles/ms/icons/red-dot.png',
    size: { width: 90, height: 90 },
    label: 'PO',
  },
  'Visit In-Tracker': {
    url: 'http://maps.google.com/mapfiles/ms/icons/orange-dot.png',
    size: { width: 90, height: 90 },
    label: 'VI',
  },
  'Visit Out-Tracker': {
    url: 'http://maps.google.com/mapfiles/ms/icons/yellow-dot.png',
    size: { width: 90, height: 90 },
    label: 'VO',
  },
  'Auto-Tracking': {
    url: img,
    size: { width: 100, height: 100 },
    label: '',
  },
  default: {
    url: 'http://maps.google.com/mapfiles/ms/icons/blue-dot.png',
    size: { width: 80, height: 80 },
    label: '',
  },
};

// Marker colors for consistent theming
const MARKER_COLORS = {
  'Punch In-Tracker': '#10B981', // Emerald Green
  'Punch Out-Tracker': '#EF4444', // Red
  'Visit In-Tracker': '#F97316', // Orange
  'Visit Out-Tracker': '#fcff4f', // Yellow
  'Auto-Tracking': '#8B5CF6', // Violet
  default: 'blue', // Orange
};

export default function LiveMap({ data, showMultipleRoutes = false, onMarkerClick }) {
  const { isLoaded, loadError } = useLoadScript({
    googleMapsApiKey: 'AIzaSyD1Uvzt4qmx6O7DcUf0gH3DfrLssx_ARfc',
    libraries: ['places', 'geometry'],
  });

  const [selectedPoint, setSelectedPoint] = useState(null);
  const [mapRef, setMapRef] = useState(null);
  const [zoom, setZoom] = useState(14);
  const [mapType, setMapType] = useState('roadmap');
  const [showLegend, setShowLegend] = useState(true);
  const [routeVisibility, setRouteVisibility] = useState(true);
  const [showAllInfoWindows, setShowAllInfoWindows] = useState(false);
  const [fullPageMode, setFullPageMode] = useState(false);

  // Process map data with memoization
  const { routePath, markers } = useMemo(() => {
    if (!data) return { routePath: [], markers: [] };

    let routePath = [];
    let markers = [];
    const seenPositions = new Set();

    // Check if data is from getStaffGeolocationsList
    if (Array.isArray(data)) {
      data.forEach((point, index) => {
        if (point.latitude && point.longitude) {
          const lat = parseFloat(point.latitude);
          const lng = parseFloat(point.longitude);
          const positionKey = `${lat.toFixed(6)},${lng.toFixed(6)}`;

          if (!isNaN(lat) && !isNaN(lng) && !seenPositions.has(positionKey)) {
            seenPositions.add(positionKey);
            routePath.push({ lat, lng });
            markers.push({
              id: `marker-${index}-${Date.now()}`,
              position: { lat, lng },
              actionType: point.actionType || 'Auto-Tracking',
              time: point.createdAt ? new Date(point.createdAt).toLocaleString() : 'N/A',
              address: point.address || point.location || 'Unknown location',
              speed: point.speed || '0',
              battery: point.battery || 'N/A',
              networkStatus: point.networkStatus || 'N/A',
              image: point.imageUrl || point.image,
              accuracy: point.accuracy || 0,
              timestamp: point.createdAt || new Date().toISOString(),
            });
          }
        }
      });
    } else if (data?.records?.geoLocation) {
      const geoLocations = data.records.geoLocation || [];
      geoLocations.forEach((location, index) => {
        if (location.coordinates && Array.isArray(location.coordinates)) {
          const lat = location.coordinates[1];
          const lng = location.coordinates[0];
          const positionKey = `${lat.toFixed(6)},${lng.toFixed(6)}`;

          if (!isNaN(lat) && !isNaN(lng) && !seenPositions.has(positionKey)) {
            seenPositions.add(positionKey);
            routePath.push({ lat, lng });
            markers.push({
              id: `marker-${index}-${Date.now()}`,
              position: { lat, lng },
              actionType: location.actionType || 'Auto-Tracking',
              time: location.createdAt ? new Date(location.createdAt).toLocaleString() : 'N/A',
              address: location.address || location.location || 'Unknown location',
              speed: location.speed || '0',
              battery: location.battery || 'N/A',
              networkStatus: location.networkStatus || 'N/A',
              image: location.imageUrl || location.image,
              distance: location.distance || '0',
              totalDistance: location.totalDistance || '0',
              accuracy: location.accuracy || 0,
              timestamp: location.createdAt || new Date().toISOString(),
            });
          }
        }
      });
    }

    // Sort markers by timestamp
    markers.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    return { routePath, markers };
  }, [data]);

  // Calculate map center
  const center = useMemo(() => {
    if (routePath.length > 0) {
      return routePath[0];
    }
    return { lat: 11.341, lng: 77.7172 }; // Default center
  }, [routePath]);

  // Get marker icon
  const getMarkerIcon = useCallback((actionType) => {
    const iconConfig = MARKER_ICONS[actionType] || MARKER_ICONS.default;
    return {
      url: iconConfig.url,
      scaledSize: new window.google.maps.Size(iconConfig.size.width, iconConfig.size.height),
    };
  }, []);

  // Get marker label
  const getMarkerLabel = useCallback((actionType, index) => {
    const iconConfig = MARKER_ICONS[actionType] || MARKER_ICONS.default;
    return {
      text: iconConfig.label || `${index + 1}`,
      color: '#FFFFFF',
      fontSize: '12px',
      fontWeight: 'bold',
    };
  }, []);

  // Handle marker click
  const handleMarkerClick = useCallback(
    (marker) => {
      setSelectedPoint(marker);
      if (onMarkerClick) {
        onMarkerClick(marker);
      }
    },
    [onMarkerClick]
  );

  // Fit bounds to show all markers
  const fitBounds = useCallback(() => {
    if (mapRef && markers.length > 0) {
      const bounds = new window.google.maps.LatLngBounds();
      markers.forEach((marker) => bounds.extend(marker.position));
      mapRef.fitBounds(bounds);
    }
  }, [mapRef, markers]);

  // Zoom in/out handlers
  const handleZoomIn = () => {
    if (mapRef) {
      mapRef.setZoom(mapRef.getZoom() + 1);
      setZoom(mapRef.getZoom());
    }
  };

  const handleZoomOut = () => {
    if (mapRef) {
      mapRef.setZoom(mapRef.getZoom() - 1);
      setZoom(mapRef.getZoom());
    }
  };

  // Toggle map type
  const toggleMapType = () => {
    const types = ['roadmap', 'satellite', 'hybrid', 'terrain'];
    const currentIndex = types.indexOf(mapType);
    const nextType = types[(currentIndex + 1) % types.length];
    setMapType(nextType);
  };

  // Toggle full page mode
  const toggleFullPageMode = () => {
    setFullPageMode(!fullPageMode);
    
    // Add/remove class to body to prevent scrolling
    if (!fullPageMode) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
  };

  // Exit full page mode on escape key
  React.useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape' && fullPageMode) {
        toggleFullPageMode();
      }
    };

    window.addEventListener('keydown', handleEscape);
    
    return () => {
      window.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = ''; // Cleanup on unmount
    };
  }, [fullPageMode]);

  if (loadError) {
    return (
      <div className="map-error">
        <div className="error-content">
          <MapPin size={48} className="error-icon" />
          <h3>Error Loading Map</h3>
          <p>Unable to load Google Maps. Please check your internet connection.</p>
        </div>
      </div>
    );
  }

  if (!isLoaded) {
    return (
      <div className="map-loading">
        <div className="spinner"></div>
        <p>Loading Map...</p>
      </div>
    );
  }

  return (
    <>
      {fullPageMode && (
        <div className="full-page-overlay" onClick={toggleFullPageMode}></div>
      )}
      
      <div className={`live-map-wrapper ${fullPageMode ? 'full-page-mode' : ''}`}>
        {/* Full Page Map - Hidden until activated */}
        {fullPageMode && (
          <div className="full-page-map">
            <GoogleMap
              mapContainerStyle={{
                width: '100vw',
                height: '100vh',
                position: 'fixed',
                top: 0,
                left: 0,
              }}
              zoom={zoom}
              center={center}
              options={{
                streetViewControl: true,
                mapTypeControl: true,
                fullscreenControl: false, // We have our own
                zoomControl: true,
                mapTypeId: mapType,
                styles: [
                  {
                    featureType: 'poi',
                    elementType: 'labels',
                    stylers: [{ visibility: 'off' }],
                  },
                ],
              }}
              onLoad={(map) => setMapRef(map)}
              onZoomChanged={() => mapRef && setZoom(mapRef.getZoom())}
            >
              {/* Draw route polyline */}
              {routePath.length > 1 && routeVisibility && (
                <Polyline
                  path={routePath}
                  options={{
                    strokeColor: '#F97316',
                    strokeOpacity: 0.7,
                    strokeWeight: 4,
                    geodesic: true,
                    icons: [
                      {
                        icon: { path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW },
                        offset: '100%',
                        repeat: '100px',
                      },
                    ],
                  }}
                />
              )}

              {/* Display markers */}
              {markers.map((marker, index) => (
                <React.Fragment key={marker.id}>
                  <Marker
                    position={marker.position}
                    onClick={() => handleMarkerClick(marker)}
                    icon={getMarkerIcon(marker.actionType)}
                    label={getMarkerLabel(marker.actionType, index)}
                    animation={selectedPoint?.id === marker.id ? window.google.maps.Animation.BOUNCE : null}
                  />

                  {/* Show accuracy circle for Auto-Tracking markers */}
                  {marker.actionType === 'Auto-Tracking' && marker.accuracy > 0 && (
                    <Circle
                      center={marker.position}
                      radius={marker.accuracy}
                      options={{
                        fillColor: '#F97316',
                        fillOpacity: 0.1,
                        strokeColor: '#F97316',
                        strokeOpacity: 0.3,
                        strokeWeight: 1,
                      }}
                    />
                  )}

                  {/* Show InfoWindow for selected point */}
                  {selectedPoint?.id === marker.id && (
                    <InfoWindow
                      position={marker.position}
                      onCloseClick={() => setSelectedPoint(null)}
                    >
                      <div className="info-window-content">
                        <div className="info-header">
                          <div
                            className="marker-badge"
                            style={{ backgroundColor: MARKER_COLORS[marker.actionType] || MARKER_COLORS.default }}
                          >
                            {MARKER_ICONS[marker.actionType]?.label || '?'}
                          </div>
                          <h4>{marker.actionType}</h4>
                        </div>

                        <div className="info-grid">
                          <div className="info-row">
                            <Clock size={14} />
                            <span>{marker.time}</span>
                          </div>

                          <div className="info-row">
                            <MapPin size={14} />
                            <span className="address">{marker.address}</span>
                          </div>

                          <div className="info-row">
                            <Navigation size={14} />
                            <span>Speed: {marker.speed} km/h</span>
                          </div>

                          <div className="info-row">
                            <Battery size={14} />
                            <span>Battery: {marker.battery}%</span>
                          </div>

                          <div className="info-row">
                            <Wifi size={14} />
                            <span>Network: {marker.networkStatus}</span>
                          </div>

                          {marker.distance && (
                            <div className="info-row">
                              <Navigation size={14} />
                              <span>Distance: {marker.distance} km</span>
                            </div>
                          )}

                          {marker.totalDistance && (
                            <div className="info-row">
                              <Map size={14} />
                              <span>Total: {marker.totalDistance} km</span>
                            </div>
                          )}
                        </div>

                        {marker.image && (
                          <div className="image-section">
                            <button onClick={() => window.open(resolveImageUrl(marker.image), '_blank')} className="view-image-btn">
                              <ImageIcon size={14} />
                              View Image
                            </button>
                          </div>
                        )}
                      </div>
                    </InfoWindow>
                  )}
                </React.Fragment>
              ))}
            </GoogleMap>

            {/* Full page controls */}
            <div className="full-page-controls">
              <div className="control-group">
                <button onClick={handleZoomIn} className="control-btn" title="Zoom In">
                  <ZoomIn size={20} />
                </button>
                <button onClick={handleZoomOut} className="control-btn" title="Zoom Out">
                  <ZoomOut size={20} />
                </button>
                <button onClick={fitBounds} className="control-btn" title="Fit Bounds">
                  <Target size={20} />
                </button>
                <button onClick={toggleMapType} className="control-btn" title="Change Map Type">
                  <Layers size={20} />
                </button>
                <button onClick={() => setRouteVisibility(!routeVisibility)} className="control-btn" title="Toggle Route">
                  <Compass size={20} />
                </button>
                <button onClick={toggleFullPageMode} className="control-btn exit-fullscreen-btn" title="Exit Full Screen">
                  <Minimize2 size={20} />
                </button>
              </div>
              
              {/* Quick stats in full page mode */}
              <div className="full-page-stats">
                <div className="stat-badge">
                  <MapPin size={14} />
                  <span>{markers.length}</span>
                </div>
                <div className="stat-badge">
                  <Navigation size={14} />
                  <span>{routePath.length - 1}</span>
                </div>
                <div className="stat-badge">
                  <span>Zoom: {zoom}</span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Normal Map View */}
        {!fullPageMode && (
          <div className="normal-map-container">
            <div className="map-header">
              <h3>Live Tracking Map</h3>
              <button onClick={toggleFullPageMode} className="fullscreen-btn" title="Full Screen Map">
                <Maximize2 size={20} />
                <span>Full Screen</span>
              </button>
            </div>

            <div className="map-content">
              {/* Map Controls */}
              <div className="map-controls">
                <button onClick={handleZoomIn} className="control-btn" title="Zoom In">
                  <ZoomIn size={20} />
                </button>
                <button onClick={handleZoomOut} className="control-btn" title="Zoom Out">
                  <ZoomOut size={20} />
                </button>
                <button onClick={fitBounds} className="control-btn" title="Fit Bounds">
                  <Target size={20} />
                </button>
                <button onClick={toggleMapType} className="control-btn" title="Change Map Type">
                  <Layers size={20} />
                </button>
                <button onClick={() => setRouteVisibility(!routeVisibility)} className="control-btn" title="Toggle Route">
                  <Compass size={20} />
                </button>
              </div>

              {/* Stats Panel */}
              <div className="stats-panel">
                <div className="stat-item">
                  <MapPin size={16} />
                  <span>{markers.length} Points</span>
                </div>
                <div className="stat-item">
                  <Navigation size={16} />
                  <span>{routePath.length > 1 ? `${routePath.length - 1} Segments` : 'No Route'}</span>
                </div>
                <div className="stat-item">
                  <Clock size={16} />
                  <span>{markers.length > 0 ? new Date(markers[markers.length - 1].timestamp).toLocaleTimeString() : '--:--'}</span>
                </div>
              </div>

              {/* Legend Panel - Bottom Left Corner */}
              {showLegend && markers.length > 0 && (
                <div className="legend-panel">
                  <div className="legend-header">
                    <h5>
                      <Map size={16} />
                      <span>Marker Legend</span>
                    </h5>
                    <button 
                      className="legend-toggle-btn" 
                      onClick={() => setShowLegend(!showLegend)}
                      title="Hide Legend"
                    >
                      ×
                    </button>
                  </div>
                  
                  <div className="legend-items">
                    {Object.entries(MARKER_COLORS).map(([type, color]) => (
                      <div key={type} className="legend-item">
                        <div className="legend-color" style={{ backgroundColor: color }}></div>
                        <span>{type.replace('-Tracker', '')}</span>
                      </div>
                    ))}
                  </div>
                  
                  <div className="legend-stats">
                    <div className="legend-stat">
                      <span>Points:</span>
                      <strong>{markers.length}</strong>
                    </div>
                    <div className="legend-stat">
                      <span>Zoom:</span>
                      <strong>{zoom}</strong>
                    </div>
                    <div className="legend-stat">
                      <span>Type:</span>
                      <strong>{mapType.charAt(0).toUpperCase() + mapType.slice(1)}</strong>
                    </div>
                  </div>
                </div>
              )}

              {/* Google Map */}
              <GoogleMap
                mapContainerStyle={mapContainerStyle}
                zoom={zoom}
                center={center}
                options={{
                  streetViewControl: false,
                  mapTypeControl: false,
                  fullscreenControl: false,
                  zoomControl: false,
                  mapTypeId: mapType,
                  styles: [
                    {
                      featureType: 'poi',
                      elementType: 'labels',
                      stylers: [{ visibility: 'off' }],
                    },
                  ],
                }}
                onLoad={(map) => setMapRef(map)}
                onZoomChanged={() => mapRef && setZoom(mapRef.getZoom())}
              >
                {/* Draw route polyline */}
                {routePath.length > 1 && routeVisibility && (
                  <Polyline
                    path={routePath}
                    options={{
                      strokeColor: '#F97316',
                      strokeOpacity: 0.7,
                      strokeWeight: 4,
                      geodesic: true,
                      icons: [
                        {
                          icon: { path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW },
                          offset: '100%',
                          repeat: '100px',
                        },
                      ],
                    }}
                  />
                )}

                {/* Display markers */}
                {markers.map((marker, index) => (
                  <React.Fragment key={marker.id}>
                    <Marker
                      position={marker.position}
                      onClick={() => handleMarkerClick(marker)}
                      icon={getMarkerIcon(marker.actionType)}
                      label={getMarkerLabel(marker.actionType, index)}
                      animation={selectedPoint?.id === marker.id ? window.google.maps.Animation.BOUNCE : null}
                    />

                    {/* Show accuracy circle for Auto-Tracking markers */}
                    {marker.actionType === 'Auto-Tracking' && marker.accuracy > 0 && (
                      <Circle
                        center={marker.position}
                        radius={marker.accuracy}
                        options={{
                          fillColor: '#F97316',
                          fillOpacity: 0.1,
                          strokeColor: '#F97316',
                          strokeOpacity: 0.3,
                          strokeWeight: 1,
                        }}
                      />
                    )}

                    {/* Show InfoWindow for selected point or all if enabled */}
                    {(selectedPoint?.id === marker.id || showAllInfoWindows) && (
                      <InfoWindow
                        position={marker.position}
                        onCloseClick={() => {
                          if (selectedPoint?.id === marker.id) setSelectedPoint(null);
                        }}
                      >
                        <div className="info-window-content">
                          <div className="info-header">
                            <div
                              className="marker-badge"
                              style={{ backgroundColor: MARKER_COLORS[marker.actionType] || MARKER_COLORS.default }}
                            >
                              {MARKER_ICONS[marker.actionType]?.label || '?'}
                            </div>
                            <h4>{marker.actionType}</h4>
                          </div>

                          <div className="info-grid">
                            <div className="info-row">
                              <Clock size={14} />
                              <span>{marker.time}</span>
                            </div>

                            <div className="info-row">
                              <MapPin size={14} />
                              <span className="address">{marker.address}</span>
                            </div>

                            <div className="info-row">
                              <Navigation size={14} />
                              <span>Speed: {marker.speed} km/h</span>
                            </div>

                            <div className="info-row">
                              <Battery size={14} />
                              <span>Battery: {marker.battery}%</span>
                            </div>

                            <div className="info-row">
                              <Wifi size={14} />
                              <span>Network: {marker.networkStatus}</span>
                            </div>

                            {marker.distance && (
                              <div className="info-row">
                                <Navigation size={14} />
                                <span>Distance: {marker.distance} km</span>
                              </div>
                            )}

                            {marker.totalDistance && (
                              <div className="info-row">
                                <Map size={14} />
                                <span>Total: {marker.totalDistance} km</span>
                              </div>
                            )}
                          </div>

                          {marker.image && (
                            <div className="image-section">
                              <button onClick={() => window.open(resolveImageUrl(marker.image), '_blank')} className="view-image-btn">
                                <ImageIcon size={14} />
                                View Image
                              </button>
                            </div>
                          )}
                        </div>
                      </InfoWindow>
                    )}
                  </React.Fragment>
                ))}
              </GoogleMap>
            </div>
          </div>
        )}
      </div>
    </>
  );
}