// employee/reducers.ts
const initialState = {
  getSettingsList: [],
  updateSettingsData: null,
  isLoading: false,
  errorMessage: null,
  getSettingsSuccess: false,
  getSettingsFailure: false,
  createSettingsSuccess: false,
  createSettingsFailure: false,
};

export default function settingsReducer(state = initialState, action: any) {
  switch (action.type) {
    case "GET_SETTINGS_SUCCESS": {
      return {
        ...state,
        getSettingsSuccess: true,
        getSettingsList: action.payload.data.data,
        getSettingsFailure: false,
      };
    }
    case "GET_SETTINGS_FAILURE": {
      return {
        ...state,
        getSettingsFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        getSettingsSuccess: false,
      };
    }
    case "RESET_GET_SETTINGS": {
      return {
        ...state,
        getSettingsSuccess: false,
        getSettingsFailure: false,
        getSettingsList: [],
        errorMessage: null,
      };
    }

    case "UPDATE_SETTINGS_SUCCESS": {
      return {
        ...state,
        updateSettingsSuccess: true,
        updateSettingsData: action.payload.data.data,
        updateSettingsFailure: false,
      };
    }
    case "UPDATE_SETTINGS_FAILURE": {
      return {
        ...state,
        updateSettingsFailure: true,
        errorMessage: action.errorMessage.errorMessage,
        updateSettingsSuccess: false,
      };
    }
    case "RESET_UPDATE_SETTINGS": {
      return {
        ...state,
        updateSettingsSuccess: false,
        updateSettingsFailure: false,
        updateSettingsData: null,
        errorMessage: null,
      };
    }

    default: {
      return state;
    }
  }
}
