// saga.ts
import { call, put, takeEvery } from 'redux-saga/effects';
import {  getDashboard } from '../../api/DashboardApi'; // Adjust the path as needed
import {
  getDashboardSuccess, getDashboardFailure
} from './actions';

// Saga to handle fetching dashboards
function* fetchDashboardSaga(action: any): Generator<any, any, any> {
  try {
    const data = yield call(getDashboard, action.payload);
    yield put(getDashboardSuccess(data));
  } catch (error: any) {
    const errorMessage = error.response && error.response.data && error.response.data.message
      ? error.response.data.message
      : error.message
        ? error.message
        : 'An unexpected error occurred';
    yield put(getDashboardFailure(errorMessage));
  }
}

export default function* dashboardSaga() {
  yield takeEvery('GET_DASHBOARD_REQUEST', fetchDashboardSaga);
}
