//Get Reducer Call--->
export const getDashboardRequest = (params?: any) => ({
  type: 'GET_DASHBOARD_REQUEST',
  payload: params,
});

export const getDashboardSuccess = (data: any) => ({
  type: 'GET_DASHBOARD_SUCCESS',
  payload: { data },
});

export const getDashboardFailure = (errorMessage: string) => ({
  type: 'GET_DASHBOARD_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetDashboard = () => ({
  type: 'RESET_GET_DASHBOARD',
});
