// GET Staff Face Training List
export const getStaffFaceTrainingRequest = (params?: any) => ({
  type: 'GET_STAFF_FACE_TRAINING_REQUEST',
  payload: params,
});

export const getStaffFaceTrainingSuccess = (data: any) => ({
  type: 'GET_STAFF_FACE_TRAINING_SUCCESS',
  payload: { data },
});

export const getStaffFaceTrainingFailure = (errorMessage: string) => ({
  type: 'GET_STAFF_FACE_TRAINING_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetStaffFaceTraining = () => ({
  type: 'RESET_GET_STAFF_FACE_TRAINING',
});

// GET Staff Face Training by ID
export const getStaffFaceTrainingByIdRequest = (staffCode: string) => ({
  type: 'GET_STAFF_FACE_TRAINING_BY_ID_REQUEST',
  payload: staffCode,
});

export const getStaffFaceTrainingByIdSuccess = (data: any) => ({
  type: 'GET_STAFF_FACE_TRAINING_BY_ID_SUCCESS',
  payload: { data },
});

export const getStaffFaceTrainingByIdFailure = (errorMessage: string) => ({
  type: 'GET_STAFF_FACE_TRAINING_BY_ID_FAILURE',
  errorMessage: { errorMessage },
});

export const resetGetStaffFaceTrainingById = () => ({
  type: 'RESET_GET_STAFF_FACE_TRAINING_BY_ID',
});