import { apiReturnCallBack } from './ApiConfig';
import apiContainer from './apiContainer';
import { Navigate } from 'react-router-dom';
const StaffFaceTraining = apiContainer.staffFaceTraining;
const StaffFaceTrainingById = apiContainer.staffFaceTrainingById;
//GET--->
export async function getStaffFaceTraining(request) {
  try {
    const response = await apiReturnCallBack("GET",StaffFaceTraining, request);
    const data = await response.json();
    if (!response.ok) {
      // Unauthorization
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />
      }
      throw new Error(data.message || JSON.stringify(data));
    }
    return data;
  } catch (error) {
    console.error(error);
    throw error;
  }
}

export async function getStaffFaceTrainingById(staffCode) {
  try {
    const url = `${StaffFaceTrainingById}/${staffCode}`;

    const response = await apiReturnCallBack("GET", url);
    const data = await response.json();

    if (!response.ok) {
      // Unauthorized
      if (data.code == 401) {
        localStorage.clear();
        return <Navigate to="/login" replace />;
      }
      throw new Error(data.message || JSON.stringify(data));
    }

    return data;

  } catch (error) {
    console.error(error);
    throw error;
  }
}
